// ============================================================
// questions.js — Excel Training question bank
// 30 questions per level x 5 levels = 150 questions
// Trilingual: ar / en / fr. In every language block:
//   q = question, o = options (o[0] is ALWAYS the correct answer —
//   script.js shuffles the options on every attempt), e = short explanation.
// Formulas are written between {{ }} and shown left-to-right as code.
// Function names use the English Excel names with "," as separator.
// ============================================================

const EXCEL_Q = [
  /* ===================== LEVEL 1 — interface, cells, entry, saving ===================== */
  { level: 1,
    ar: { q: "ما امتداد ملف مصنف إكسل الحديث (منذ إصدار 2007)؟", o: [".xlsx", ".docx", ".pptx", ".accdb"], e: "مصنفات إكسل الحديثة تُحفظ بصيغة ‎.xlsx‎ (Open XML). أما ‎.xls‎ فهي صيغة الإصدارات القديمة 97-2003." },
    en: { q: "What is the file extension of a modern Excel workbook (since Excel 2007)?", o: [".xlsx", ".docx", ".pptx", ".accdb"], e: "Modern Excel workbooks are saved as .xlsx (Open XML). The older .xls format belongs to Excel 97-2003." },
    fr: { q: "Quelle est l'extension d'un classeur Excel moderne (depuis Excel 2007) ?", o: [".xlsx", ".docx", ".pptx", ".accdb"], e: "Les classeurs Excel modernes sont enregistrés en .xlsx (Open XML). L'ancien format .xls correspond à Excel 97-2003." } },
  { level: 1,
    ar: { q: "ماذا نسمّي نقطة تقاطع صف مع عمود في ورقة العمل؟", o: ["خلية", "نطاق", "مصنف", "جدول"], e: "الخلية هي الوحدة الأساسية في إكسل، وتقع عند تقاطع عمود وصف، مثل الخلية B3." },
    en: { q: "What do we call the intersection of a row and a column in a worksheet?", o: ["A cell", "A range", "A workbook", "A table"], e: "A cell is the basic unit of Excel, located where a column meets a row, e.g. cell B3." },
    fr: { q: "Comment appelle-t-on l'intersection d'une ligne et d'une colonne dans une feuille ?", o: ["Une cellule", "Une plage", "Un classeur", "Un tableau"], e: "La cellule est l'unité de base d'Excel, située à l'intersection d'une colonne et d'une ligne, par ex. la cellule B3." } },
  { level: 1,
    ar: { q: "ما عنوان الخلية الواقعة في العمود C والصف 5؟", o: ["C5", "5C", "R5C", "C:5"], e: "يُكتب عنوان الخلية بحرف العمود أولًا ثم رقم الصف: C5." },
    en: { q: "What is the address of the cell in column C and row 5?", o: ["C5", "5C", "R5C", "C:5"], e: "A cell address is written as the column letter followed by the row number: C5." },
    fr: { q: "Quelle est l'adresse de la cellule située dans la colonne C et la ligne 5 ?", o: ["C5", "5C", "R5C", "C:5"], e: "L'adresse d'une cellule s'écrit avec la lettre de colonne puis le numéro de ligne : C5." } },
  { level: 1,
    ar: { q: "بماذا تُعنون الأعمدة والصفوف في إكسل افتراضيًا؟", o: ["الأعمدة بالحروف والصفوف بالأرقام", "الأعمدة بالأرقام والصفوف بالحروف", "كلاهما بالأرقام", "كلاهما بالحروف"], e: "الأعمدة: A, B, C… والصفوف: 1, 2, 3… (يمكن تغيير ذلك إلى نمط R1C1 من الخيارات، لكنه ليس الافتراضي)." },
    en: { q: "By default, how are columns and rows labelled in Excel?", o: ["Columns with letters, rows with numbers", "Columns with numbers, rows with letters", "Both with numbers", "Both with letters"], e: "Columns are A, B, C… and rows are 1, 2, 3… (the R1C1 style can be turned on in Options, but it is not the default)." },
    fr: { q: "Par défaut, comment les colonnes et les lignes sont-elles nommées dans Excel ?", o: ["Colonnes en lettres, lignes en chiffres", "Colonnes en chiffres, lignes en lettres", "Les deux en chiffres", "Les deux en lettres"], e: "Les colonnes sont A, B, C… et les lignes 1, 2, 3… (le style L1C1 existe dans les Options, mais ce n'est pas le réglage par défaut)." } },
  { level: 1,
    ar: { q: "كم عدد الصفوف في ورقة عمل إكسل الحديثة (2007 وما بعده)؟", o: ["1,048,576", "65,536", "16,384", "1,000,000"], e: "الورقة الحديثة تضم 1,048,576 صفًا و16,384 عمودًا. الرقم 65,536 كان حدّ الإصدارات القديمة." },
    en: { q: "How many rows does a modern Excel worksheet (2007 and later) have?", o: ["1,048,576", "65,536", "16,384", "1,000,000"], e: "A modern sheet has 1,048,576 rows and 16,384 columns. 65,536 was the limit in old versions." },
    fr: { q: "Combien de lignes compte une feuille Excel moderne (2007 et après) ?", o: ["1 048 576", "65 536", "16 384", "1 000 000"], e: "Une feuille moderne compte 1 048 576 lignes et 16 384 colonnes. 65 536 était la limite des anciennes versions." } },
  { level: 1,
    ar: { q: "ما اسم آخر عمود في ورقة إكسل الحديثة؟", o: ["XFD", "ZZZ", "IV", "XFZ"], e: "آخر عمود هو XFD وهو العمود رقم 16,384. أما IV فكان آخر عمود في إكسل 2003 (256 عمودًا)." },
    en: { q: "What is the name of the last column in a modern Excel sheet?", o: ["XFD", "ZZZ", "IV", "XFZ"], e: "The last column is XFD, column number 16,384. IV was the last column in Excel 2003 (256 columns)." },
    fr: { q: "Quel est le nom de la dernière colonne d'une feuille Excel moderne ?", o: ["XFD", "ZZZ", "IV", "XFZ"], e: "La dernière colonne est XFD, la colonne n° 16 384. IV était la dernière colonne d'Excel 2003 (256 colonnes)." } },
  { level: 1,
    ar: { q: "ما وظيفة «مربع الاسم» (Name Box) الموجود يسار شريط الصيغة؟", o: ["يعرض عنوان الخلية النشطة ويسمح بالانتقال إلى خلية أو تسمية نطاق", "يعرض الصيغة الموجودة داخل الخلية", "يعرض اسم الملف", "يغيّر نسبة التكبير"], e: "مربع الاسم يُظهر عنوان الخلية المحددة (مثل A1)، ويمكنك كتابة عنوان فيه للانتقال إليه أو إعطاء اسم لنطاق." },
    en: { q: "What is the role of the Name Box, left of the formula bar?", o: ["It shows the active cell's address and lets you jump to a cell or name a range", "It shows the formula inside the cell", "It shows the file name", "It changes the zoom level"], e: "The Name Box shows the selected cell's address (e.g. A1); you can type an address there to jump to it, or give a range a name." },
    fr: { q: "Quel est le rôle de la Zone Nom, à gauche de la barre de formule ?", o: ["Afficher l'adresse de la cellule active et permettre d'aller à une cellule ou de nommer une plage", "Afficher la formule contenue dans la cellule", "Afficher le nom du fichier", "Modifier le niveau de zoom"], e: "La Zone Nom affiche l'adresse de la cellule sélectionnée (ex. A1) ; on peut y taper une adresse pour s'y rendre ou nommer une plage." } },
  { level: 1,
    ar: { q: "ماذا يعرض «شريط الصيغة» عند تحديد خلية تحتوي معادلة؟", o: ["المعادلة نفسها، بينما تعرض الخلية نتيجتها", "النتيجة فقط", "تنسيق الخلية", "عنوان الخلية فقط"], e: "الخلية تُظهر نتيجة الحساب، أما شريط الصيغة فيُظهر المعادلة الفعلية ويسمح بتعديلها." },
    en: { q: "When you select a cell containing a formula, what does the formula bar show?", o: ["The formula itself, while the cell shows its result", "Only the result", "The cell's formatting", "Only the cell address"], e: "The cell displays the calculated result; the formula bar shows the actual formula and lets you edit it." },
    fr: { q: "Quand on sélectionne une cellule contenant une formule, que montre la barre de formule ?", o: ["La formule elle-même, tandis que la cellule affiche le résultat", "Uniquement le résultat", "La mise en forme de la cellule", "Uniquement l'adresse de la cellule"], e: "La cellule affiche le résultat du calcul ; la barre de formule montre la formule réelle et permet de la modifier." } },
  { level: 1,
    ar: { q: "ما الفرق بين المصنف (Workbook) وورقة العمل (Worksheet)؟", o: ["المصنف هو الملف، ويحتوي ورقة عمل واحدة أو أكثر", "ورقة العمل هي الملف، وتحتوي عدة مصنفات", "لا فرق بينهما", "المصنف خاص بالمخططات فقط"], e: "ملف إكسل كامل = مصنف، وبداخله أوراق عمل تظهر كألسنة (تبويبات) أسفل الشاشة." },
    en: { q: "What is the difference between a workbook and a worksheet?", o: ["The workbook is the file; it contains one or more worksheets", "The worksheet is the file; it contains several workbooks", "There is no difference", "A workbook is only for charts"], e: "A whole Excel file is a workbook; inside it are worksheets, shown as tabs at the bottom of the window." },
    fr: { q: "Quelle est la différence entre un classeur et une feuille de calcul ?", o: ["Le classeur est le fichier ; il contient une ou plusieurs feuilles", "La feuille est le fichier ; elle contient plusieurs classeurs", "Il n'y a aucune différence", "Un classeur sert uniquement aux graphiques"], e: "Un fichier Excel complet est un classeur ; il contient des feuilles, affichées sous forme d'onglets en bas de la fenêtre." } },
  { level: 1,
    ar: { q: "بأي رمز يجب أن تبدأ كل معادلة في إكسل؟", o: ["=", "#", "\"", "?"], e: "تبدأ المعادلات بعلامة = حتى يفهم إكسل أن ما بعدها حساب وليس نصًا، مثل {{=A1+B1}}." },
    en: { q: "Which symbol must every Excel formula start with?", o: ["=", "#", "\"", "?"], e: "Formulas start with = so Excel knows what follows is a calculation, not text, e.g. {{=A1+B1}}." },
    fr: { q: "Par quel symbole doit commencer toute formule Excel ?", o: ["=", "#", "\"", "?"], e: "Les formules commencent par = pour qu'Excel comprenne qu'il s'agit d'un calcul et non de texte, ex. {{=A1+B1}}." } },
  { level: 1,
    ar: { q: "في ورقة من اليسار إلى اليمين، كيف تُحاذى الأرقام داخل الخلايا افتراضيًا؟", o: ["إلى اليمين", "إلى اليسار", "في الوسط", "إلى الأعلى"], e: "افتراضيًا تُحاذى الأرقام والتواريخ إلى اليمين والنصوص إلى اليسار (ويحدث العكس في ورقة من اليمين إلى اليسار). هذه علامة سريعة لمعرفة هل القيمة رقم أم نص." },
    en: { q: "In a left-to-right sheet, how are numbers aligned in cells by default?", o: ["To the right", "To the left", "Centered", "At the top"], e: "By default numbers and dates align right and text aligns left (reversed in a right-to-left sheet). It is a quick way to tell a number from text." },
    fr: { q: "Dans une feuille de gauche à droite, comment les nombres sont-ils alignés par défaut ?", o: ["À droite", "À gauche", "Au centre", "En haut"], e: "Par défaut, nombres et dates s'alignent à droite et le texte à gauche (inversé dans une feuille de droite à gauche). C'est un moyen rapide de distinguer un nombre d'un texte." } },
  { level: 1,
    ar: { q: "بعد كتابة قيمة في خلية، ماذا يحدث افتراضيًا عند الضغط على Enter؟", o: ["تُعتمد القيمة وينتقل التحديد إلى الخلية التي تحتها", "تُحذف القيمة", "يُحفظ الملف", "تنتقل إلى الورقة التالية"], e: "Enter يعتمد الإدخال وينقلك للأسفل، وTab يعتمده وينقلك للخلية المجاورة في الصف. يمكن تغيير اتجاه Enter من الخيارات." },
    en: { q: "After typing a value in a cell, what happens by default when you press Enter?", o: ["The value is confirmed and the selection moves to the cell below", "The value is deleted", "The file is saved", "You move to the next sheet"], e: "Enter confirms the entry and moves down; Tab confirms it and moves to the next cell in the row. Enter's direction can be changed in Options." },
    fr: { q: "Après avoir tapé une valeur dans une cellule, que se passe-t-il par défaut avec Entrée ?", o: ["La valeur est validée et la sélection descend à la cellule du dessous", "La valeur est supprimée", "Le fichier est enregistré", "On passe à la feuille suivante"], e: "Entrée valide la saisie et descend ; Tab la valide et passe à la cellule voisine de la ligne. La direction d'Entrée se règle dans les Options." } },
  { level: 1,
    ar: { q: "أثناء الكتابة داخل خلية، ماذا تفعل مفتاح Esc؟", o: ["تلغي الإدخال الحالي وتُبقي المحتوى القديم كما كان", "تحذف الورقة", "تحفظ الملف", "تغلق إكسل"], e: "Esc يُلغي ما تكتبه قبل اعتماده، فتعود الخلية إلى محتواها السابق." },
    en: { q: "While typing inside a cell, what does the Esc key do?", o: ["It cancels the current entry and keeps the old content", "It deletes the sheet", "It saves the file", "It closes Excel"], e: "Esc cancels what you are typing before it is confirmed, so the cell goes back to its previous content." },
    fr: { q: "Pendant la saisie dans une cellule, que fait la touche Échap ?", o: ["Elle annule la saisie en cours et conserve l'ancien contenu", "Elle supprime la feuille", "Elle enregistre le fichier", "Elle ferme Excel"], e: "Échap annule ce que l'on tape avant validation : la cellule retrouve son contenu précédent." } },
  { level: 1,
    ar: { q: "ما وظيفة المفتاح F2 في إكسل؟", o: ["تعديل محتوى الخلية النشطة مباشرة", "إعادة تسمية الورقة", "فتح التعليمات", "حفظ الملف"], e: "F2 يفتح وضع التحرير داخل الخلية ويضع المؤشر في نهاية محتواها، دون أن تمسح ما فيها." },
    en: { q: "What does the F2 key do in Excel?", o: ["Edit the active cell's content in place", "Rename the sheet", "Open Help", "Save the file"], e: "F2 enters edit mode in the cell with the cursor at the end of its content, without erasing it." },
    fr: { q: "Que fait la touche F2 dans Excel ?", o: ["Modifier directement le contenu de la cellule active", "Renommer la feuille", "Ouvrir l'aide", "Enregistrer le fichier"], e: "F2 passe en mode modification dans la cellule, curseur à la fin du contenu, sans l'effacer." } },
  { level: 1,
    ar: { q: "ماذا يفعل المفتاح F12 في إكسل؟", o: ["فتح نافذة «حفظ باسم»", "الطباعة", "التدقيق الإملائي", "إدراج ورقة جديدة"], e: "F12 يفتح «حفظ باسم» لحفظ نسخة باسم أو مكان أو صيغة مختلفة، بينما Ctrl+S يحفظ الملف الحالي." },
    en: { q: "What does the F12 key do in Excel?", o: ["Opens the “Save As” dialog", "Prints", "Runs spell check", "Inserts a new sheet"], e: "F12 opens Save As to save a copy under another name, place or format, while Ctrl+S saves the current file." },
    fr: { q: "Que fait la touche F12 dans Excel ?", o: ["Ouvre la boîte « Enregistrer sous »", "Imprime", "Lance la vérification orthographique", "Insère une nouvelle feuille"], e: "F12 ouvre « Enregistrer sous » pour enregistrer une copie sous un autre nom, emplacement ou format ; Ctrl+S enregistre le fichier actuel." } },
  { level: 1,
    ar: { q: "كم خلية يضم النطاق {{A1:C3}}؟", o: ["9", "6", "3", "2"], e: "النطاق من A1 إلى C3 يشمل 3 أعمدة (A, B, C) × 3 صفوف (1, 2, 3) = 9 خلايا. النقطتان «:» تعني «إلى»." },
    en: { q: "How many cells are in the range {{A1:C3}}?", o: ["9", "6", "3", "2"], e: "A1 to C3 covers 3 columns (A, B, C) × 3 rows (1, 2, 3) = 9 cells. The colon “:” means “to”." },
    fr: { q: "Combien de cellules contient la plage {{A1:C3}} ?", o: ["9", "6", "3", "2"], e: "De A1 à C3 : 3 colonnes (A, B, C) × 3 lignes (1, 2, 3) = 9 cellules. Les deux-points « : » signifient « jusqu'à »." } },
  { level: 1,
    ar: { q: "كيف تُدرج ورقة عمل جديدة بسرعة؟", o: ["بالنقر على زر + بجانب ألسنة الأوراق أو بالاختصار Shift+F11", "بالضغط على Ctrl+N", "بالضغط على F12", "بالنقر المزدوج على الخلية A1"], e: "زر + أو Shift+F11 يضيف ورقة جديدة داخل المصنف نفسه. أما Ctrl+N فيُنشئ مصنفًا (ملفًا) جديدًا." },
    en: { q: "How do you quickly insert a new worksheet?", o: ["Click the + button next to the sheet tabs, or press Shift+F11", "Press Ctrl+N", "Press F12", "Double-click cell A1"], e: "The + button or Shift+F11 adds a sheet inside the same workbook. Ctrl+N creates a new workbook (file)." },
    fr: { q: "Comment insérer rapidement une nouvelle feuille de calcul ?", o: ["Cliquer sur le bouton + à côté des onglets ou appuyer sur Maj+F11", "Appuyer sur Ctrl+N", "Appuyer sur F12", "Double-cliquer sur la cellule A1"], e: "Le bouton + ou Maj+F11 ajoute une feuille dans le même classeur. Ctrl+N crée un nouveau classeur (fichier)." } },
  { level: 1,
    ar: { q: "ما أسرع طريقة لإعادة تسمية ورقة عمل؟", o: ["النقر المزدوج على لسان الورقة ثم كتابة الاسم الجديد", "الضغط على F2 داخل خلية", "حفظ الملف باسم جديد", "النقر المزدوج على رأس العمود"], e: "النقر المزدوج على لسان الورقة (أو زر الفأرة الأيمن ← إعادة تسمية) يجعل اسمها قابلًا للتعديل." },
    en: { q: "What is the quickest way to rename a worksheet?", o: ["Double-click the sheet tab and type the new name", "Press F2 inside a cell", "Save the file under a new name", "Double-click the column header"], e: "Double-clicking the sheet tab (or right-click → Rename) makes its name editable." },
    fr: { q: "Quel est le moyen le plus rapide de renommer une feuille ?", o: ["Double-cliquer sur l'onglet de la feuille et taper le nouveau nom", "Appuyer sur F2 dans une cellule", "Enregistrer le fichier sous un nouveau nom", "Double-cliquer sur l'en-tête de colonne"], e: "Un double-clic sur l'onglet (ou clic droit → Renommer) rend le nom modifiable." } },
  { level: 1,
    ar: { q: "ما هي «مقبض التعبئة» (Fill Handle)؟", o: ["المربع الصغير في زاوية التحديد، يُسحب لنسخ المحتوى أو إكمال سلسلة", "زر لحفظ الملف", "شريط التمرير الأفقي", "أيقونة لون التعبئة"], e: "عند سحب مقبض التعبئة يقوم إكسل بنسخ القيمة أو المعادلة، أو بإكمال سلسلة (أرقام، أيام، أشهر…)." },
    en: { q: "What is the Fill Handle?", o: ["The small square at the corner of a selection, dragged to copy content or extend a series", "A button that saves the file", "The horizontal scroll bar", "The fill colour icon"], e: "Dragging the fill handle copies the value or formula, or extends a series (numbers, days, months…)." },
    fr: { q: "Qu'est-ce que la poignée de recopie ?", o: ["Le petit carré au coin de la sélection, que l'on fait glisser pour recopier ou prolonger une série", "Un bouton qui enregistre le fichier", "La barre de défilement horizontale", "L'icône de couleur de remplissage"], e: "Faire glisser la poignée recopie la valeur ou la formule, ou prolonge une série (nombres, jours, mois…)." } },
  { level: 1,
    ar: { q: "كتبت 1 في A1 و2 في A2، ثم حددت الخليتين وسحبت مقبض التعبئة للأسفل. ماذا يظهر في الخلايا التالية؟", o: ["3، 4، 5…", "1، 2، 1، 2…", "2، 2، 2…", "رسالة خطأ"], e: "عند تحديد قيمتين يستنتج إكسل الفرق بينهما (+1) ويكمل السلسلة. لو حددت خلية واحدة فقط لنسخها غالبًا." },
    en: { q: "You type 1 in A1 and 2 in A2, select both and drag the fill handle down. What appears next?", o: ["3, 4, 5…", "1, 2, 1, 2…", "2, 2, 2…", "An error message"], e: "With two values selected, Excel infers the step (+1) and extends the series. With a single number selected it would usually just copy it." },
    fr: { q: "Vous tapez 1 en A1 et 2 en A2, sélectionnez les deux et tirez la poignée vers le bas. Qu'obtient-on ?", o: ["3, 4, 5…", "1, 2, 1, 2…", "2, 2, 2…", "Un message d'erreur"], e: "Avec deux valeurs sélectionnées, Excel déduit le pas (+1) et prolonge la série. Avec un seul nombre, il le recopierait généralement." } },
  { level: 1,
    ar: { q: "ظهرت العلامات ##### داخل خلية تحتوي رقمًا أو تاريخًا. ماذا يعني ذلك غالبًا؟", o: ["العمود أضيق من أن يعرض القيمة", "المعادلة خاطئة", "الخلية محذوفة", "الملف مصاب بفيروس"], e: "القيمة سليمة لكن عرض العمود لا يكفي لعرضها. وسّع العمود فتظهر. (وقد تظهر أيضًا مع تاريخ أو وقت سالب)." },
    en: { q: "##### appears in a cell containing a number or date. What does it usually mean?", o: ["The column is too narrow to display the value", "The formula is wrong", "The cell was deleted", "The file has a virus"], e: "The value is fine, but the column is not wide enough to show it. Widen the column. (It can also appear with a negative date or time.)" },
    fr: { q: "##### apparaît dans une cellule contenant un nombre ou une date. Que signifie-t-il le plus souvent ?", o: ["La colonne est trop étroite pour afficher la valeur", "La formule est fausse", "La cellule a été supprimée", "Le fichier contient un virus"], e: "La valeur est correcte, mais la colonne est trop étroite pour l'afficher. Élargissez-la. (Cela arrive aussi avec une date ou une heure négative.)" } },
  { level: 1,
    ar: { q: "كيف تضبط عرض عمود تلقائيًا ليناسب أطول محتوى فيه؟", o: ["بالنقر المزدوج على الحد الفاصل يمين رأس العمود", "بالنقر المزدوج داخل أي خلية", "بالضغط على Ctrl+A", "بتغيير حجم الخط"], e: "النقر المزدوج على حدود رأس العمود يطبّق «احتواء تلقائي» (AutoFit) حسب أطول قيمة." },
    en: { q: "How do you automatically fit a column's width to its longest content?", o: ["Double-click the boundary on the right of the column header", "Double-click inside any cell", "Press Ctrl+A", "Change the font size"], e: "Double-clicking the column header boundary applies AutoFit based on the longest value." },
    fr: { q: "Comment ajuster automatiquement la largeur d'une colonne à son contenu le plus long ?", o: ["Double-cliquer sur la bordure droite de l'en-tête de colonne", "Double-cliquer dans n'importe quelle cellule", "Appuyer sur Ctrl+A", "Changer la taille de police"], e: "Un double-clic sur la bordure de l'en-tête applique l'ajustement automatique selon la valeur la plus longue." } },
  { level: 1,
    ar: { q: "إلى أين ينقلك الاختصار Ctrl+Home؟", o: ["إلى الخلية A1 (بداية الورقة)", "إلى آخر خلية مستخدمة", "إلى الورقة الأولى", "إلى بداية النص داخل الخلية"], e: "Ctrl+Home يعيدك إلى A1 من أي مكان في الورقة (أو إلى أول خلية غير مجمّدة إذا كانت الأجزاء مجمّدة)، بينما Ctrl+End ينقلك إلى آخر خلية مستخدمة." },
    en: { q: "Where does Ctrl+Home take you?", o: ["To cell A1 (start of the sheet)", "To the last used cell", "To the first sheet", "To the start of the text in the cell"], e: "Ctrl+Home goes back to A1 from anywhere (or to the first unfrozen cell when panes are frozen); Ctrl+End goes to the last used cell." },
    fr: { q: "Où vous mène le raccourci Ctrl+Origine (Home) ?", o: ["À la cellule A1 (début de la feuille)", "À la dernière cellule utilisée", "À la première feuille", "Au début du texte dans la cellule"], e: "Ctrl+Origine ramène en A1 depuis n'importe où (ou à la première cellule non figée si des volets sont figés) ; Ctrl+Fin mène à la dernière cellule utilisée." } },
  { level: 1,
    ar: { q: "حددت الصف 5 واخترت «إدراج». أين يظهر الصف الجديد؟", o: ["فوق الصف 5، وتنزل البيانات القديمة للأسفل", "تحت الصف 5", "في نهاية الورقة", "يحلّ محل الصف 5 ويحذف بياناته"], e: "يُدرج إكسل الصف الجديد فوق الصف المحدد، فيصبح هو الصف 5 وتنزل الصفوف الأخرى درجة واحدة. ونفس المبدأ للأعمدة (يُدرج العمود قبل المحدد)." },
    en: { q: "You select row 5 and choose Insert. Where does the new row appear?", o: ["Above row 5, with the old data shifted down", "Below row 5", "At the end of the sheet", "It replaces row 5 and deletes its data"], e: "Excel inserts the new row above the selected row; it becomes row 5 and the others move down one. Columns work the same way (inserted before the selected one)." },
    fr: { q: "Vous sélectionnez la ligne 5 et choisissez Insérer. Où apparaît la nouvelle ligne ?", o: ["Au-dessus de la ligne 5, les anciennes données descendent", "Sous la ligne 5", "À la fin de la feuille", "Elle remplace la ligne 5 et efface ses données"], e: "Excel insère la nouvelle ligne au-dessus de la ligne sélectionnée ; elle devient la ligne 5 et les autres descendent d'un cran. Même principe pour les colonnes (insertion avant la colonne choisie)." } },
  { level: 1,
    ar: { q: "ماذا يحدث عند الضغط على مفتاح Delete بعد تحديد خلية منسّقة تحتوي قيمة؟", o: ["يُمسح المحتوى ويبقى التنسيق", "تُحذف الخلية وتُزاح الخلايا المجاورة", "يُمسح التنسيق فقط", "يُحذف الصف بالكامل"], e: "Delete يمسح المحتويات فقط. لمسح التنسيق أيضًا استخدم: الصفحة الرئيسية ← مسح ← مسح الكل." },
    en: { q: "What happens when you press Delete on a formatted cell containing a value?", o: ["The content is cleared but the formatting stays", "The cell is removed and neighbours shift", "Only the formatting is cleared", "The whole row is deleted"], e: "Delete clears contents only. To also remove formatting use Home → Clear → Clear All." },
    fr: { q: "Que se passe-t-il quand on appuie sur Suppr sur une cellule mise en forme contenant une valeur ?", o: ["Le contenu est effacé mais la mise en forme reste", "La cellule est supprimée et les voisines se décalent", "Seule la mise en forme est effacée", "Toute la ligne est supprimée"], e: "Suppr efface uniquement le contenu. Pour effacer aussi la mise en forme : Accueil → Effacer → Effacer tout." } },
  { level: 1,
    ar: { q: "كيف تبدأ سطرًا جديدًا داخل الخلية نفسها أثناء الكتابة؟", o: ["Alt+Enter", "Ctrl+Enter", "Shift+Enter", "Tab"], e: "Alt+Enter يضيف فاصل سطر داخل الخلية. أما Ctrl+Enter فيكتب القيمة نفسها في كل الخلايا المحددة." },
    en: { q: "How do you start a new line inside the same cell while typing?", o: ["Alt+Enter", "Ctrl+Enter", "Shift+Enter", "Tab"], e: "Alt+Enter adds a line break inside the cell. Ctrl+Enter writes the same entry into all selected cells." },
    fr: { q: "Comment aller à la ligne dans la même cellule pendant la saisie ?", o: ["Alt+Entrée", "Ctrl+Entrée", "Maj+Entrée", "Tab"], e: "Alt+Entrée insère un saut de ligne dans la cellule. Ctrl+Entrée écrit la même saisie dans toutes les cellules sélectionnées." } },
  { level: 1,
    ar: { q: "ما فائدة «تجميد الأجزاء» (Freeze Panes) من تبويب «عرض»؟", o: ["إبقاء صفوف العناوين أو الأعمدة الأولى ظاهرة أثناء التمرير", "منع تعديل الخلايا", "إخفاء الصفوف", "تسريع الحسابات"], e: "التجميد يُثبّت العناوين في مكانها بينما تتحرك بقية البيانات، وهو مفيد جدًا في الجداول الطويلة. لا علاقة له بالحماية." },
    en: { q: "What is Freeze Panes (View tab) used for?", o: ["Keeping header rows or first columns visible while scrolling", "Preventing cells from being edited", "Hiding rows", "Speeding up calculations"], e: "Freezing keeps headers in place while the rest of the data scrolls — very useful for long tables. It has nothing to do with protection." },
    fr: { q: "À quoi sert « Figer les volets » (onglet Affichage) ?", o: ["Garder les lignes d'en-tête ou premières colonnes visibles pendant le défilement", "Empêcher la modification des cellules", "Masquer des lignes", "Accélérer les calculs"], e: "Figer garde les en-têtes en place pendant que le reste défile — très utile pour les longs tableaux. Cela n'a rien à voir avec la protection." } },
  { level: 1,
    ar: { q: "تريد إدخال رقم هاتف مثل 0550123456 مع الحفاظ على الصفر في بدايته. ما الحل البسيط؟", o: ["كتابة فاصلة علوية قبله: '0550123456", "كتابته بخط عريض", "توسيع العمود", "كتابته بين قوسين"], e: "الفاصلة العلوية ' تجعل إكسل يخزّن القيمة كنص فيبقى الصفر. ويمكن أيضًا تنسيق الخلية كـ«نص» قبل الكتابة. الفاصلة نفسها لا تظهر في الخلية." },
    en: { q: "You want to enter a phone number like 0550123456 and keep its leading zero. What is the simple fix?", o: ["Type an apostrophe first: '0550123456", "Make it bold", "Widen the column", "Put it in brackets"], e: "The apostrophe ' makes Excel store the entry as text, so the zero stays. You can also format the cell as Text before typing. The apostrophe itself is not displayed." },
    fr: { q: "Vous voulez saisir un numéro comme 0550123456 en gardant le zéro initial. Quelle est la solution simple ?", o: ["Taper une apostrophe avant : '0550123456", "Le mettre en gras", "Élargir la colonne", "Le mettre entre parenthèses"], e: "L'apostrophe ' fait stocker la saisie comme texte, donc le zéro est conservé. On peut aussi mettre la cellule au format Texte avant de taper. L'apostrophe n'est pas affichée." } },
  { level: 1,
    ar: { q: "أين ترى بسرعة مجموع ومتوسط الخلايا الرقمية التي حددتها دون كتابة أي معادلة؟", o: ["في شريط الحالة أسفل النافذة", "في مربع الاسم", "في شريط العنوان", "في تبويب «ملف»"], e: "شريط الحالة يعرض تلقائيًا المتوسط والعدد والمجموع للخلايا المحددة، ويمكن إضافة الحد الأدنى والأقصى بالنقر عليه بزر الفأرة الأيمن." },
    en: { q: "Where can you quickly see the sum and average of selected numeric cells without any formula?", o: ["In the status bar at the bottom of the window", "In the Name Box", "In the title bar", "In the File tab"], e: "The status bar automatically shows Average, Count and Sum for the selection; right-click it to add Min and Max." },
    fr: { q: "Où voir rapidement la somme et la moyenne des cellules sélectionnées sans écrire de formule ?", o: ["Dans la barre d'état en bas de la fenêtre", "Dans la Zone Nom", "Dans la barre de titre", "Dans l'onglet Fichier"], e: "La barre d'état affiche automatiquement Moyenne, Nombre et Somme de la sélection ; un clic droit permet d'ajouter Min et Max." } },
  { level: 1,
    ar: { q: "ماذا يحدث عند حفظ مصنف من عدة أوراق بصيغة CSV؟", o: ["تُحفظ الورقة النشطة فقط كقيم نصية مفصولة، دون تنسيق أو معادلات", "تُحفظ كل الأوراق بتنسيقها", "تُحفظ المعادلات والمخططات", "يتحول الملف إلى PDF"], e: "CSV ملف نصي بسيط: ورقة واحدة، قيم مفصولة بفاصلة (أو فاصلة منقوطة حسب إعدادات المنطقة)، بلا تنسيق ولا مخططات ولا معادلات." },
    en: { q: "What happens when you save a multi-sheet workbook as CSV?", o: ["Only the active sheet is saved, as plain separated values, without formatting or formulas", "All sheets are saved with their formatting", "Formulas and charts are kept", "The file becomes a PDF"], e: "CSV is plain text: one sheet, values separated by commas (or semicolons depending on regional settings), with no formatting, charts or formulas." },
    fr: { q: "Que se passe-t-il quand on enregistre un classeur de plusieurs feuilles au format CSV ?", o: ["Seule la feuille active est enregistrée, en valeurs séparées, sans mise en forme ni formules", "Toutes les feuilles sont enregistrées avec leur mise en forme", "Les formules et graphiques sont conservés", "Le fichier devient un PDF"], e: "Le CSV est du texte brut : une seule feuille, des valeurs séparées par des virgules (ou points-virgules selon les paramètres régionaux), sans mise en forme, graphiques ni formules." } },
  /* ===================== LEVEL 2 — formatting, number/date formats, SUM AVERAGE MIN MAX ===================== */
  { level: 2,
    ar: { q: "الخلايا A1 إلى A4 تحتوي 2، 4، 6، 8. ما نتيجة {{=SUM(A1:A4)}}؟", o: ["20", "8", "4", "2468"], e: "SUM تجمع كل القيم في النطاق: 2+4+6+8 = 20." },
    en: { q: "Cells A1 to A4 contain 2, 4, 6, 8. What does {{=SUM(A1:A4)}} return?", o: ["20", "8", "4", "2468"], e: "SUM adds every value in the range: 2+4+6+8 = 20." },
    fr: { q: "Les cellules A1 à A4 contiennent 2, 4, 6, 8. Que renvoie {{=SUM(A1:A4)}} ?", o: ["20", "8", "4", "2468"], e: "SUM (SOMME en version française) additionne toutes les valeurs : 2+4+6+8 = 20." } },
  { level: 2,
    ar: { q: "ما نتيجة {{=AVERAGE(10,20,30,40)}}؟", o: ["25", "100", "40", "10"], e: "المتوسط = المجموع ÷ العدد = 100 ÷ 4 = 25." },
    en: { q: "What does {{=AVERAGE(10,20,30,40)}} return?", o: ["25", "100", "40", "10"], e: "Average = sum ÷ count = 100 ÷ 4 = 25." },
    fr: { q: "Que renvoie {{=AVERAGE(10,20,30,40)}} ?", o: ["25", "100", "40", "10"], e: "AVERAGE (MOYENNE) = somme ÷ nombre = 100 ÷ 4 = 25." } },
  { level: 2,
    ar: { q: "ما نتيجة {{=MAX(3,9,-2,7)}}؟", o: ["9", "7", "-2", "17"], e: "MAX تُرجع أكبر قيمة في القائمة، وهي 9." },
    en: { q: "What does {{=MAX(3,9,-2,7)}} return?", o: ["9", "7", "-2", "17"], e: "MAX returns the largest value in the list: 9." },
    fr: { q: "Que renvoie {{=MAX(3,9,-2,7)}} ?", o: ["9", "7", "-2", "17"], e: "MAX renvoie la plus grande valeur de la liste : 9." } },
  { level: 2,
    ar: { q: "ما نتيجة {{=MIN(5,-3,0,8)}}؟", o: ["-3", "0", "5", "8"], e: "MIN تُرجع أصغر قيمة، والعدد السالب -3 أصغر من الصفر." },
    en: { q: "What does {{=MIN(5,-3,0,8)}} return?", o: ["-3", "0", "5", "8"], e: "MIN returns the smallest value; the negative number -3 is smaller than zero." },
    fr: { q: "Que renvoie {{=MIN(5,-3,0,8)}} ?", o: ["-3", "0", "5", "8"], e: "MIN renvoie la plus petite valeur ; le nombre négatif -3 est inférieur à zéro." } },
  { level: 2,
    ar: { q: "A1 = 10، والخلية A2 فارغة، وA3 = 20. ما نتيجة {{=AVERAGE(A1:A3)}}؟", o: ["15", "10", "30", "0"], e: "AVERAGE تتجاهل الخلايا الفارغة، فتحسب (10+20) ÷ 2 = 15." },
    en: { q: "A1 = 10, A2 is empty, A3 = 20. What does {{=AVERAGE(A1:A3)}} return?", o: ["15", "10", "30", "0"], e: "AVERAGE ignores empty cells, so it computes (10+20) ÷ 2 = 15." },
    fr: { q: "A1 = 10, A2 est vide, A3 = 20. Que renvoie {{=AVERAGE(A1:A3)}} ?", o: ["15", "10", "30", "0"], e: "AVERAGE ignore les cellules vides : (10+20) ÷ 2 = 15." } },
  { level: 2,
    ar: { q: "A1 = 10، وA2 = 0، وA3 = 20. ما نتيجة {{=AVERAGE(A1:A3)}}؟", o: ["10", "15", "30", "0"], e: "الصفر قيمة حقيقية تدخل في الحساب (بعكس الخلية الفارغة): (10+0+20) ÷ 3 = 10." },
    en: { q: "A1 = 10, A2 = 0, A3 = 20. What does {{=AVERAGE(A1:A3)}} return?", o: ["10", "15", "30", "0"], e: "Zero is a real value and is counted (unlike an empty cell): (10+0+20) ÷ 3 = 10." },
    fr: { q: "A1 = 10, A2 = 0, A3 = 20. Que renvoie {{=AVERAGE(A1:A3)}} ?", o: ["10", "15", "30", "0"], e: "Zéro est une vraie valeur, elle est comptée (contrairement à une cellule vide) : (10+0+20) ÷ 3 = 10." } },
  { level: 2,
    ar: { q: "A1 = 5، وA2 تحتوي النص «abc»، وA3 = 10. ما نتيجة {{=SUM(A1:A3)}}؟", o: ["15", "#VALUE!", "0", "5"], e: "SUM تتجاهل النصوص الموجودة في النطاق فتُرجع 15. أما {{=A1+A2+A3}} فتُرجع الخطأ #VALUE! لأن عامل الجمع + لا يقبل النص." },
    en: { q: "A1 = 5, A2 contains the text “abc”, A3 = 10. What does {{=SUM(A1:A3)}} return?", o: ["15", "#VALUE!", "0", "5"], e: "SUM ignores text inside a range, so it returns 15. By contrast {{=A1+A2+A3}} returns #VALUE! because the + operator cannot add text." },
    fr: { q: "A1 = 5, A2 contient le texte « abc », A3 = 10. Que renvoie {{=SUM(A1:A3)}} ?", o: ["15", "#VALUE!", "0", "5"], e: "SUM ignore le texte d'une plage : résultat 15. En revanche {{=A1+A2+A3}} renvoie #VALEUR! car l'opérateur + ne peut pas additionner du texte." } },
  { level: 2,
    ar: { q: "ما اختصار «الجمع التلقائي» (AutoSum) الذي يُدرج دالة SUM تلقائيًا؟", o: ["Alt+=", "Ctrl+S", "Ctrl+=", "Shift+F3"], e: "Alt+= يُدرج {{=SUM()}} ويقترح النطاق المجاور تلقائيًا. أما Shift+F3 فيفتح نافذة «إدراج دالة»." },
    en: { q: "What is the AutoSum shortcut that inserts a SUM automatically?", o: ["Alt+=", "Ctrl+S", "Ctrl+=", "Shift+F3"], e: "Alt+= inserts {{=SUM()}} and suggests the adjacent range. Shift+F3 opens the Insert Function dialog." },
    fr: { q: "Quel est le raccourci de la Somme automatique qui insère SUM automatiquement ?", o: ["Alt+=", "Ctrl+S", "Ctrl+=", "Maj+F3"], e: "Alt+= insère {{=SUM()}} (=SOMME()) et propose la plage adjacente. Maj+F3 ouvre la boîte « Insérer une fonction »." } },
  { level: 2,
    ar: { q: "ما نتيجة {{=2+3*4}}؟", o: ["14", "20", "24", "9"], e: "الضرب يُنفَّذ قبل الجمع: 3×4 = 12 ثم 2+12 = 14." },
    en: { q: "What does {{=2+3*4}} return?", o: ["14", "20", "24", "9"], e: "Multiplication comes before addition: 3×4 = 12, then 2+12 = 14." },
    fr: { q: "Que renvoie {{=2+3*4}} ?", o: ["14", "20", "24", "9"], e: "La multiplication passe avant l'addition : 3×4 = 12, puis 2+12 = 14." } },
  { level: 2,
    ar: { q: "ما نتيجة {{=(2+3)*4}}؟", o: ["20", "14", "24", "9"], e: "الأقواس تُحسب أولًا: (2+3) = 5 ثم 5×4 = 20." },
    en: { q: "What does {{=(2+3)*4}} return?", o: ["20", "14", "24", "9"], e: "Brackets are evaluated first: (2+3) = 5, then 5×4 = 20." },
    fr: { q: "Que renvoie {{=(2+3)*4}} ?", o: ["20", "14", "24", "9"], e: "Les parenthèses sont calculées d'abord : (2+3) = 5, puis 5×4 = 20." } },
  { level: 2,
    ar: { q: "ما نتيجة {{=2^3}}؟", o: ["8", "6", "5", "9"], e: "الرمز ^ يعني الأس (القوة): 2³ = 2×2×2 = 8." },
    en: { q: "What does {{=2^3}} return?", o: ["8", "6", "5", "9"], e: "The ^ symbol means “to the power of”: 2³ = 2×2×2 = 8." },
    fr: { q: "Que renvoie {{=2^3}} ?", o: ["8", "6", "5", "9"], e: "Le symbole ^ signifie « puissance » : 2³ = 2×2×2 = 8." } },
  { level: 2,
    ar: { q: "كيف يخزّن إكسل التواريخ داخليًا؟", o: ["كأرقام تسلسلية (عدد الأيام منذ 1 يناير 1900)", "كنصوص عادية", "كصور", "كمعادلات"], e: "التاريخ رقم تسلسلي (الرقم 1 = 1/1/1900 في ويندوز) يظهر بتنسيق تاريخ، ولهذا يمكن جمع الأيام إلى التواريخ وطرحها من بعضها." },
    en: { q: "How does Excel store dates internally?", o: ["As serial numbers (days since 1 January 1900)", "As plain text", "As images", "As formulas"], e: "A date is a serial number (1 = 1/1/1900 on Windows) displayed with a date format — which is why you can add days to dates and subtract dates." },
    fr: { q: "Comment Excel stocke-t-il les dates en interne ?", o: ["Comme des numéros de série (jours depuis le 1er janvier 1900)", "Comme du texte", "Comme des images", "Comme des formules"], e: "Une date est un numéro de série (1 = 01/01/1900 sous Windows) affiché avec un format de date ; c'est pourquoi on peut ajouter des jours et soustraire des dates." } },
  { level: 2,
    ar: { q: "A1 = 1 مارس 2026 وB1 = 11 مارس 2026. ما نتيجة {{=B1-A1}} إذا كانت خلية النتيجة بتنسيق «عام»؟", o: ["10", "11", "مارس", "خطأ"], e: "طرح تاريخين يعطي عدد الأيام بينهما: 10. إذا ظهرت النتيجة كتاريخ غريب فغيّر تنسيق الخلية إلى «عام» أو «رقم»." },
    en: { q: "A1 = 1 March 2026 and B1 = 11 March 2026. What does {{=B1-A1}} return in a General-format cell?", o: ["10", "11", "March", "An error"], e: "Subtracting two dates gives the number of days between them: 10. If you see an odd date instead, change the cell format to General or Number." },
    fr: { q: "A1 = 1er mars 2026 et B1 = 11 mars 2026. Que renvoie {{=B1-A1}} dans une cellule au format Standard ?", o: ["10", "11", "Mars", "Une erreur"], e: "Soustraire deux dates donne le nombre de jours entre elles : 10. Si une date étrange s'affiche, mettez la cellule au format Standard ou Nombre." } },
  { level: 2,
    ar: { q: "خلية تحتوي 0.25، ثم طبّقت عليها تنسيق «نسبة مئوية». ماذا يظهر؟", o: ["25%", "0.25%", "2500%", "25"], e: "تنسيق النسبة المئوية يضرب القيمة المعروضة في 100: 0.25 تظهر 25%. القيمة المخزنة تبقى 0.25." },
    en: { q: "A cell contains 0.25 and you apply the Percentage format. What is displayed?", o: ["25%", "0.25%", "2500%", "25"], e: "The Percentage format displays the value × 100: 0.25 shows as 25%. The stored value stays 0.25." },
    fr: { q: "Une cellule contient 0,25 et vous appliquez le format Pourcentage. Qu'affiche-t-elle ?", o: ["25 %", "0,25 %", "2500 %", "25"], e: "Le format Pourcentage affiche la valeur × 100 : 0,25 devient 25 %. La valeur stockée reste 0,25." } },
  { level: 2,
    ar: { q: "تحتوي A1 القيمة 3.14159 وتظهر 3.14 بسبب تنسيق «تقليل المنازل العشرية». ما نتيجة {{=A1*100}}؟", o: ["314.159", "314", "314.00", "3.14"], e: "التنسيق يغيّر طريقة العرض فقط، والحساب يتم دائمًا على القيمة الكاملة المخزنة 3.14159. لتغيير القيمة نفسها استخدم ROUND." },
    en: { q: "A1 holds 3.14159 but shows 3.14 after “Decrease Decimal”. What does {{=A1*100}} return?", o: ["314.159", "314", "314.00", "3.14"], e: "Formatting only changes the display; calculations always use the full stored value 3.14159. To change the value itself, use ROUND." },
    fr: { q: "A1 contient 3,14159 mais affiche 3,14 après « Réduire les décimales ». Que renvoie {{=A1*100}} ?", o: ["314,159", "314", "314,00", "3,14"], e: "La mise en forme ne change que l'affichage ; les calculs utilisent toujours la valeur complète 3,14159. Pour changer la valeur elle-même, utilisez ROUND (ARRONDI)." } },
  { level: 2,
    ar: { q: "ما الذي يميّز تنسيق «محاسبة» (Accounting) عن تنسيق «عملة»؟", o: ["يحاذي رموز العملة والفواصل العشرية في العمود ويعرض الأصفار كشَرطة", "يحوّل العملة تلقائيًا بسعر الصرف", "يخفي الأرقام السالبة", "لا يقبل المنازل العشرية"], e: "كلاهما يعرض رمز العملة، لكن «محاسبة» يثبّت الرمز عند حافة الخلية ويحاذي الفواصل العشرية ويُظهر الصفر «-»، فتبدو الأعمدة المالية مرتبة." },
    en: { q: "What distinguishes the Accounting format from the Currency format?", o: ["It lines up currency symbols and decimal points in a column and shows zeros as a dash", "It converts currencies at the exchange rate", "It hides negative numbers", "It does not allow decimals"], e: "Both show a currency symbol, but Accounting pins the symbol to the cell edge, aligns decimal points and shows zero as “-”, so financial columns look tidy." },
    fr: { q: "Qu'est-ce qui distingue le format Comptabilité du format Monétaire ?", o: ["Il aligne symboles monétaires et virgules décimales dans la colonne et affiche les zéros par un tiret", "Il convertit les devises au taux de change", "Il masque les nombres négatifs", "Il n'accepte pas les décimales"], e: "Les deux affichent un symbole monétaire, mais Comptabilité colle le symbole au bord de la cellule, aligne les décimales et affiche zéro par « - » : les colonnes financières sont plus nettes." } },
  { level: 2,
    ar: { q: "عند استخدام «دمج وتوسيط» على خلايا تحتوي كلها قيمًا، ماذا يحدث للبيانات؟", o: ["تبقى قيمة الخلية الأولى (العلوية) فقط وتُحذف البقية", "تُجمع كل القيم في خلية واحدة", "تُدمج النصوص بفواصل", "لا يُسمح بالدمج"], e: "إكسل يحذّرك: الدمج يحتفظ بقيمة الخلية الأولى فقط. بديل أفضل للعناوين: «توسيط عبر التحديد» من نافذة تنسيق الخلايا." },
    en: { q: "When you use Merge & Center on cells that all contain values, what happens to the data?", o: ["Only the first (upper-left) cell's value is kept; the rest are discarded", "All values are summed into one cell", "The texts are joined with commas", "Merging is not allowed"], e: "Excel warns you: merging keeps only the first cell's value. A safer choice for titles is “Center Across Selection” in Format Cells." },
    fr: { q: "Avec « Fusionner et centrer » sur des cellules qui contiennent toutes des valeurs, que deviennent les données ?", o: ["Seule la valeur de la première cellule (en haut à gauche) est conservée ; les autres sont perdues", "Toutes les valeurs sont additionnées", "Les textes sont joints par des virgules", "La fusion est interdite"], e: "Excel avertit : la fusion ne garde que la valeur de la première cellule. Pour les titres, préférez « Centrer sur plusieurs colonnes » dans Format de cellule." } },
  { level: 2,
    ar: { q: "ما وظيفة أداة «نسخ التنسيق» (Format Painter، رمز الفرشاة)؟", o: ["نسخ تنسيق خلية وتطبيقه على خلايا أخرى", "نسخ القيم فقط", "تلوين الخلايا الفارغة", "رسم مخطط"], e: "حدد الخلية المنسقة، اضغط الفرشاة، ثم انقر على الخلايا الهدف. النقر المزدوج على الفرشاة يُبقيها فعّالة لعدة مرات حتى تضغط Esc." },
    en: { q: "What does the Format Painter (brush icon) do?", o: ["Copies a cell's formatting and applies it to other cells", "Copies values only", "Colours empty cells", "Draws a chart"], e: "Select the formatted cell, click the brush, then click the target cells. Double-clicking the brush keeps it active for several uses until you press Esc." },
    fr: { q: "Que fait l'outil Reproduire la mise en forme (icône pinceau) ?", o: ["Copier la mise en forme d'une cellule et l'appliquer à d'autres", "Copier uniquement les valeurs", "Colorer les cellules vides", "Dessiner un graphique"], e: "Sélectionnez la cellule mise en forme, cliquez le pinceau puis les cellules cibles. Un double-clic sur le pinceau le garde actif jusqu'à Échap." } },
  { level: 2,
    ar: { q: "ما الاختصار الذي يفتح نافذة «تنسيق الخلايا»؟", o: ["Ctrl+1", "Ctrl+F", "Ctrl+P", "Ctrl+B"], e: "Ctrl+1 يفتح نافذة تنسيق الخلايا بكل تبويباتها: رقم، محاذاة، خط، حدود، تعبئة، حماية." },
    en: { q: "Which shortcut opens the Format Cells dialog?", o: ["Ctrl+1", "Ctrl+F", "Ctrl+P", "Ctrl+B"], e: "Ctrl+1 opens Format Cells with all its tabs: Number, Alignment, Font, Border, Fill, Protection." },
    fr: { q: "Quel raccourci ouvre la boîte Format de cellule ?", o: ["Ctrl+1", "Ctrl+F", "Ctrl+P", "Ctrl+B"], e: "Ctrl+1 ouvre Format de cellule avec tous ses onglets : Nombre, Alignement, Police, Bordure, Remplissage, Protection." } },
  { level: 2,
    ar: { q: "طبّقت التنسيق المخصص {{0000}} على خلية تحتوي 7. ماذا يظهر؟", o: ["0007", "7000", "7", "####"], e: "كل 0 في التنسيق المخصص يمثل خانة إجبارية، فيُكمل إكسل بأصفار على اليسار: 0007. القيمة تبقى 7." },
    en: { q: "You apply the custom format {{0000}} to a cell containing 7. What is displayed?", o: ["0007", "7000", "7", "####"], e: "Each 0 in a custom format is a mandatory digit, so Excel pads with leading zeros: 0007. The value is still 7." },
    fr: { q: "Vous appliquez le format personnalisé {{0000}} à une cellule contenant 7. Qu'affiche-t-elle ?", o: ["0007", "7000", "7", "####"], e: "Chaque 0 d'un format personnalisé est un chiffre obligatoire : Excel complète par des zéros à gauche : 0007. La valeur reste 7." } },
  { level: 2,
    ar: { q: "ماذا يعرض رمز التنسيق المخصص {{dddd}} على خلية تحتوي تاريخًا؟", o: ["اسم اليوم كاملًا (مثل: الخميس)", "رقم اليوم من خانتين", "اسم الشهر مختصرًا", "السنة"], e: "d = رقم اليوم، dd = رقم اليوم بخانتين، ddd = اسم اليوم مختصرًا، dddd = اسم اليوم كاملًا." },
    en: { q: "What does the custom format code {{dddd}} display for a date?", o: ["The full weekday name (e.g. Thursday)", "The two-digit day number", "The abbreviated month name", "The year"], e: "d = day number, dd = two-digit day, ddd = short weekday name, dddd = full weekday name." },
    fr: { q: "Qu'affiche le code de format personnalisé {{dddd}} (jjjj en français) pour une date ?", o: ["Le nom complet du jour (ex. jeudi)", "Le numéro du jour sur deux chiffres", "Le nom abrégé du mois", "L'année"], e: "d = numéro du jour, dd = jour sur deux chiffres, ddd = nom court du jour, dddd = nom complet. (En Excel français : j, jj, jjj, jjjj.)" } },
  { level: 2,
    ar: { q: "ما الاختصار الذي يُدرج تاريخ اليوم كقيمة ثابتة لا تتغير؟", o: ["Ctrl+;", "Ctrl+Shift+;", "Ctrl+D", "F5"], e: "Ctrl+; يكتب تاريخ اليوم كقيمة ثابتة، وCtrl+Shift+; يكتب الوقت الحالي." },
    en: { q: "Which shortcut inserts today's date as a fixed value?", o: ["Ctrl+;", "Ctrl+Shift+;", "Ctrl+D", "F5"], e: "Ctrl+; types today's date as a fixed value; Ctrl+Shift+; types the current time." },
    fr: { q: "Quel raccourci insère la date du jour comme valeur fixe ?", o: ["Ctrl+;", "Ctrl+Maj+;", "Ctrl+D", "F5"], e: "Ctrl+; saisit la date du jour en valeur fixe ; Ctrl+Maj+; saisit l'heure actuelle." } },
  { level: 2,
    ar: { q: "ما الفرق بين الدالة {{=TODAY()}} والاختصار Ctrl+;؟", o: ["TODAY تتحدث تلقائيًا كل يوم عند إعادة الحساب، والاختصار يكتب تاريخًا ثابتًا", "لا فرق بينهما", "TODAY تكتب الوقت أيضًا", "الاختصار يتحدث تلقائيًا"], e: "استخدم TODAY للحسابات التي تعتمد على تاريخ اليوم (مثل الأقدمية)، واستخدم Ctrl+; لتسجيل تاريخ حدث لا يجب أن يتغير. أما NOW فتُرجع التاريخ والوقت." },
    en: { q: "What is the difference between {{=TODAY()}} and the Ctrl+; shortcut?", o: ["TODAY updates automatically each day on recalculation; the shortcut types a fixed date", "There is no difference", "TODAY also writes the time", "The shortcut updates automatically"], e: "Use TODAY for calculations that depend on the current date (e.g. seniority) and Ctrl+; to record the date of an event that must not change. NOW returns date and time." },
    fr: { q: "Quelle est la différence entre {{=TODAY()}} et le raccourci Ctrl+; ?", o: ["TODAY se met à jour chaque jour au recalcul ; le raccourci saisit une date fixe", "Aucune différence", "TODAY écrit aussi l'heure", "Le raccourci se met à jour automatiquement"], e: "Utilisez TODAY (AUJOURDHUI) pour les calculs liés à la date du jour (ex. ancienneté) et Ctrl+; pour noter une date qui ne doit pas changer. NOW (MAINTENANT) renvoie date et heure." } },
  { level: 2,
    ar: { q: "أي خيار من قائمة «الحدود» يرسم خطوطًا حول كل خلية من الخلايا المحددة؟", o: ["كافة الحدود", "حدود خارجية", "حد سفلي", "بلا حدود"], e: "«كافة الحدود» يرسم شبكة كاملة داخل التحديد وحوله، أما «حدود خارجية» فيرسم إطارًا حول النطاق كله فقط." },
    en: { q: "Which Borders option draws lines around every selected cell?", o: ["All Borders", "Outside Borders", "Bottom Border", "No Border"], e: "All Borders draws a full grid inside and around the selection; Outside Borders only outlines the whole range." },
    fr: { q: "Quelle option de Bordures trace des lignes autour de chaque cellule sélectionnée ?", o: ["Toutes les bordures", "Bordures extérieures", "Bordure inférieure", "Aucune bordure"], e: "« Toutes les bordures » trace une grille complète dans et autour de la sélection ; « Bordures extérieures » encadre seulement l'ensemble de la plage." } },
  { level: 2,
    ar: { q: "ماذا يفعل زر «التفاف النص» (Wrap Text)؟", o: ["يعرض النص الطويل على عدة أسطر داخل الخلية بزيادة ارتفاع الصف", "يصغّر الخط حتى يتسع النص", "يدمج الخلية مع جاراتها", "يدوّر النص 90 درجة"], e: "التفاف النص يُبقي عرض العمود كما هو ويُنزل النص لأسطر متعددة. خيار «احتواء مع تصغير» هو الذي يصغّر الخط." },
    en: { q: "What does the Wrap Text button do?", o: ["Shows long text on several lines inside the cell by increasing row height", "Shrinks the font until the text fits", "Merges the cell with its neighbours", "Rotates the text 90 degrees"], e: "Wrap Text keeps the column width and breaks the text into several lines. “Shrink to fit” is the option that reduces the font." },
    fr: { q: "Que fait le bouton « Renvoyer à la ligne automatiquement » ?", o: ["Affiche un texte long sur plusieurs lignes dans la cellule en augmentant la hauteur de ligne", "Réduit la police jusqu'à ce que le texte tienne", "Fusionne la cellule avec ses voisines", "Fait pivoter le texte de 90 degrés"], e: "Le renvoi à la ligne garde la largeur de colonne et répartit le texte sur plusieurs lignes. C'est « Ajuster » qui réduit la police." } },
  { level: 2,
    ar: { q: "كم خلية تجمعها المعادلة {{=SUM(A1:A3,C1)}}؟", o: ["4", "2", "6", "9"], e: "الفاصلة تفصل بين وسيطات مستقلة: النطاق A1:A3 (3 خلايا) + الخلية C1 = 4 خلايا." },
    en: { q: "How many cells does {{=SUM(A1:A3,C1)}} add up?", o: ["4", "2", "6", "9"], e: "The comma separates independent arguments: range A1:A3 (3 cells) + cell C1 = 4 cells." },
    fr: { q: "Combien de cellules additionne {{=SUM(A1:A3,C1)}} ?", o: ["4", "2", "6", "9"], e: "La virgule (point-virgule en Excel français) sépare des arguments indépendants : la plage A1:A3 (3 cellules) + la cellule C1 = 4 cellules." } },
  { level: 2,
    ar: { q: "ماذا تحسب المعادلة {{=MAX(A1:A10)-MIN(A1:A10)}}؟", o: ["المدى: الفرق بين أكبر قيمة وأصغر قيمة", "المتوسط", "المجموع", "عدد القيم"], e: "طرح أصغر قيمة من أكبر قيمة يعطي «المدى»، وهو مقياس بسيط لتشتت البيانات." },
    en: { q: "What does {{=MAX(A1:A10)-MIN(A1:A10)}} calculate?", o: ["The range: the difference between the largest and smallest values", "The average", "The total", "The number of values"], e: "Subtracting the smallest value from the largest gives the range, a simple measure of how spread out the data is." },
    fr: { q: "Que calcule {{=MAX(A1:A10)-MIN(A1:A10)}} ?", o: ["L'étendue : l'écart entre la plus grande et la plus petite valeur", "La moyenne", "Le total", "Le nombre de valeurs"], e: "Soustraire la plus petite valeur de la plus grande donne l'étendue, une mesure simple de la dispersion des données." } },
  { level: 2,
    ar: { q: "ما الخطأ الذي يظهر عند القسمة على صفر أو على خلية فارغة؟", o: ["#DIV/0!", "#VALUE!", "#N/A", "#REF!"], e: "#DIV/0! تعني قسمة على صفر. #VALUE! نوع بيانات خاطئ، #N/A قيمة غير موجودة، #REF! مرجع محذوف." },
    en: { q: "Which error appears when you divide by zero or by an empty cell?", o: ["#DIV/0!", "#VALUE!", "#N/A", "#REF!"], e: "#DIV/0! means division by zero. #VALUE! = wrong data type, #N/A = value not available, #REF! = deleted reference." },
    fr: { q: "Quelle erreur apparaît quand on divise par zéro ou par une cellule vide ?", o: ["#DIV/0!", "#VALEUR!", "#N/A", "#REF!"], e: "#DIV/0! signifie division par zéro. #VALEUR! = mauvais type de donnée, #N/A = valeur non disponible, #REF! = référence supprimée." } },
  { level: 2,
    ar: { q: "كتبت مباشرة 25% داخل خلية فارغة. ما القيمة التي يخزّنها إكسل فعليًا؟", o: ["0.25", "25", "النص «25%»", "2.5"], e: "عند كتابة رقم متبوع بـ% يطبّق إكسل تنسيق النسبة المئوية ويخزّن القيمة مقسومة على 100، أي 0.25، فتعمل في الحسابات مباشرة." },
    en: { q: "You type 25% directly into an empty cell. What value does Excel actually store?", o: ["0.25", "25", "The text “25%”", "2.5"], e: "When you type a number followed by %, Excel applies the Percentage format and stores the value divided by 100, i.e. 0.25, so it works directly in calculations." },
    fr: { q: "Vous tapez directement 25 % dans une cellule vide. Quelle valeur Excel stocke-t-il réellement ?", o: ["0,25", "25", "Le texte « 25 % »", "2,5"], e: "Quand on tape un nombre suivi de %, Excel applique le format Pourcentage et stocke la valeur divisée par 100, soit 0,25, utilisable directement dans les calculs." } },
  { level: 2,
    ar: { q: "ما نتيجة {{=ROUND(2.567,2)}}؟", o: ["2.57", "2.56", "2.6", "3"], e: "ROUND تقرّب القيمة نفسها (لا العرض فقط) إلى عدد المنازل المطلوب: الرقم الثالث 7 ≥ 5 فيُقرَّب إلى 2.57." },
    en: { q: "What does {{=ROUND(2.567,2)}} return?", o: ["2.57", "2.56", "2.6", "3"], e: "ROUND rounds the value itself (not just the display) to the requested decimals: the third digit 7 ≥ 5, so it rounds to 2.57." },
    fr: { q: "Que renvoie {{=ROUND(2.567,2)}} ?", o: ["2,57", "2,56", "2,6", "3"], e: "ROUND (ARRONDI) arrondit la valeur elle-même (pas seulement l'affichage) au nombre de décimales demandé : le 3e chiffre 7 ≥ 5, donc 2,57." } },
  /* ===================== LEVEL 3 — references, IF, COUNTIF, SUMIF, sort & filter ===================== */
  { level: 3,
    ar: { q: "في B1 المعادلة {{=A1*2}}. نسختها إلى B2. ما المعادلة الناتجة في B2؟", o: ["{{=A2*2}}", "{{=A1*2}}", "{{=B1*2}}", "{{=A2*3}}"], e: "المرجع A1 نسبي، فعند النسخ صفًا واحدًا للأسفل يتحرك معه ويصبح A2. الأرقام الثابتة مثل 2 لا تتغير." },
    en: { q: "B1 contains {{=A1*2}}. You copy it to B2. What formula is in B2?", o: ["{{=A2*2}}", "{{=A1*2}}", "{{=B1*2}}", "{{=A2*3}}"], e: "A1 is a relative reference, so copying one row down shifts it to A2. Constants like 2 do not change." },
    fr: { q: "B1 contient {{=A1*2}}. Vous la copiez en B2. Quelle formule obtient-on en B2 ?", o: ["{{=A2*2}}", "{{=A1*2}}", "{{=B1*2}}", "{{=A2*3}}"], e: "A1 est une référence relative : copiée une ligne plus bas, elle devient A2. Les constantes comme 2 ne changent pas." } },
  { level: 3,
    ar: { q: "في C1 المعادلة {{=$A$1*B1}}. نسختها إلى C2. ما المعادلة الناتجة؟", o: ["{{=$A$1*B2}}", "{{=$A$2*B2}}", "{{=$A$1*B1}}", "{{=A2*B2}}"], e: "علامة $ تثبّت العمود والصف، فيبقى $A$1 كما هو (مرجع مطلق)، بينما يتحرك B1 النسبي إلى B2." },
    en: { q: "C1 contains {{=$A$1*B1}}. You copy it to C2. What formula results?", o: ["{{=$A$1*B2}}", "{{=$A$2*B2}}", "{{=$A$1*B1}}", "{{=A2*B2}}"], e: "The $ signs lock both column and row, so $A$1 stays the same (absolute reference) while the relative B1 becomes B2." },
    fr: { q: "C1 contient {{=$A$1*B1}}. Vous la copiez en C2. Quelle formule obtient-on ?", o: ["{{=$A$1*B2}}", "{{=$A$2*B2}}", "{{=$A$1*B1}}", "{{=A2*B2}}"], e: "Les $ bloquent la colonne et la ligne : $A$1 ne bouge pas (référence absolue), tandis que B1, relative, devient B2." } },
  { level: 3,
    ar: { q: "أثناء تحرير معادلة والمؤشر على المرجع A1، ماذا يفعل الضغط المتكرر على F4؟", o: ["يتنقل بين $A$1 ثم A$1 ثم $A1 ثم A1", "يحذف المرجع", "يحسب المعادلة", "يحوّل المرجع إلى نص"], e: "F4 هو أسرع طريقة لإضافة علامات $: مطلق كامل ← صف ثابت ← عمود ثابت ← نسبي." },
    en: { q: "While editing a formula with the cursor on reference A1, what does pressing F4 repeatedly do?", o: ["Cycles through $A$1, A$1, $A1, then A1", "Deletes the reference", "Calculates the formula", "Turns the reference into text"], e: "F4 is the fastest way to add $ signs: fully absolute → row locked → column locked → relative." },
    fr: { q: "En modifiant une formule, curseur sur la référence A1, que fait un appui répété sur F4 ?", o: ["Il alterne entre $A$1, A$1, $A1 puis A1", "Il supprime la référence", "Il calcule la formule", "Il transforme la référence en texte"], e: "F4 est le moyen le plus rapide d'ajouter des $ : absolue → ligne bloquée → colonne bloquée → relative." } },
  { level: 3,
    ar: { q: "ماذا يعني المرجع المختلط {{A$1}}؟", o: ["الصف 1 ثابت والعمود يتغير عند النسخ", "العمود A ثابت والصف يتغير", "كلاهما ثابت", "كلاهما يتغير"], e: "علامة $ تثبّت ما يأتي بعدها مباشرة: هنا قبل الرقم 1، إذن الصف ثابت والعمود حر." },
    en: { q: "What does the mixed reference {{A$1}} mean?", o: ["Row 1 is locked; the column changes when copied", "Column A is locked; the row changes", "Both are locked", "Both change"], e: "A $ locks what immediately follows it: here it is before 1, so the row is fixed and the column is free." },
    fr: { q: "Que signifie la référence mixte {{A$1}} ?", o: ["La ligne 1 est bloquée ; la colonne change à la recopie", "La colonne A est bloquée ; la ligne change", "Les deux sont bloquées", "Les deux changent"], e: "Le $ bloque ce qui le suit directement : ici il précède 1, donc la ligne est fixe et la colonne libre." } },
  { level: 3,
    ar: { q: "في B1 المعادلة {{=$A1}}. نسختها إلى C2 (عمود لليمين وصف للأسفل). ما الناتج؟", o: ["{{=$A2}}", "{{=$B2}}", "{{=$A1}}", "{{=B2}}"], e: "العمود A مثبّت بعلامة $ فلا يتغير، أما الصف 1 فنسبي فيزيد بمقدار صف واحد ويصبح 2." },
    en: { q: "B1 contains {{=$A1}}. You copy it to C2 (one column right, one row down). What results?", o: ["{{=$A2}}", "{{=$B2}}", "{{=$A1}}", "{{=B2}}"], e: "Column A is locked by $ so it stays; row 1 is relative, so it moves down one and becomes 2." },
    fr: { q: "B1 contient {{=$A1}}. Vous la copiez en C2 (une colonne à droite, une ligne plus bas). Résultat ?", o: ["{{=$A2}}", "{{=$B2}}", "{{=$A1}}", "{{=B2}}"], e: "La colonne A est bloquée par $ et reste ; la ligne 1 est relative et descend d'un cran pour devenir 2." } },
  { level: 3,
    ar: { q: "لإنشاء جدول ضرب: الأرقام في العمود A (من A2) وفي الصف 1 (من B1). ما المعادلة الصحيحة في B2 لتُنسخ على كامل الجدول؟", o: ["{{=$A2*B$1}}", "{{=A2*B1}}", "{{=$A$2*$B$1}}", "{{=A$2*$B1}}"], e: "نثبّت العمود A للقيم العمودية ($A2) ونثبّت الصف 1 للقيم الأفقية (B$1)، فيعمل النسخ في الاتجاهين معًا." },
    en: { q: "To build a multiplication table with numbers in column A (from A2) and row 1 (from B1), which formula in B2 can be copied across the whole table?", o: ["{{=$A2*B$1}}", "{{=A2*B1}}", "{{=$A$2*$B$1}}", "{{=A$2*$B1}}"], e: "Lock column A for the vertical values ($A2) and row 1 for the horizontal values (B$1), so copying works in both directions." },
    fr: { q: "Pour une table de multiplication avec des nombres en colonne A (dès A2) et en ligne 1 (dès B1), quelle formule en B2 peut être recopiée sur tout le tableau ?", o: ["{{=$A2*B$1}}", "{{=A2*B1}}", "{{=$A$2*$B$1}}", "{{=A$2*$B1}}"], e: "On bloque la colonne A pour les valeurs verticales ($A2) et la ligne 1 pour les valeurs horizontales (B$1) : la recopie fonctionne dans les deux sens." } },
  { level: 3,
    ar: { q: "A1 = 10. ما نتيجة {{=IF(A1>=10,\"Pass\",\"Fail\")}}؟", o: ["Pass", "Fail", "TRUE", "خطأ"], e: "الشرط 10 >= 10 صحيح (أكبر من أو يساوي)، فتُرجع IF القيمة الثانية «Pass»." },
    en: { q: "A1 = 10. What does {{=IF(A1>=10,\"Pass\",\"Fail\")}} return?", o: ["Pass", "Fail", "TRUE", "An error"], e: "The test 10 >= 10 is true (greater than or equal), so IF returns its second argument, “Pass”." },
    fr: { q: "A1 = 10. Que renvoie {{=IF(A1>=10,\"Pass\",\"Fail\")}} ?", o: ["Pass", "Fail", "TRUE", "Une erreur"], e: "Le test 10 >= 10 est vrai (supérieur ou égal), donc IF (SI) renvoie son 2e argument, « Pass »." } },
  { level: 3,
    ar: { q: "ما الترتيب الصحيح لوسيطات الدالة IF؟", o: ["الشرط، القيمة إذا كان صحيحًا، القيمة إذا كان خاطئًا", "القيمة إذا كان صحيحًا، الشرط، القيمة إذا كان خاطئًا", "الشرط، القيمة إذا كان خاطئًا، القيمة إذا كان صحيحًا", "النطاق، الشرط، المجموع"], e: "الصيغة: {{IF(logical_test, value_if_true, value_if_false)}}." },
    en: { q: "What is the correct argument order of the IF function?", o: ["Test, value if true, value if false", "Value if true, test, value if false", "Test, value if false, value if true", "Range, criteria, sum"], e: "Syntax: {{IF(logical_test, value_if_true, value_if_false)}}." },
    fr: { q: "Quel est l'ordre correct des arguments de la fonction IF (SI) ?", o: ["Test, valeur si vrai, valeur si faux", "Valeur si vrai, test, valeur si faux", "Test, valeur si faux, valeur si vrai", "Plage, critère, somme"], e: "Syntaxe : {{IF(logical_test, value_if_true, value_if_false)}} — en français SI(test_logique; valeur_si_vrai; valeur_si_faux)." } },
  { level: 3,
    ar: { q: "A1 = 3. ما نتيجة {{=IF(A1>5,\"Yes\")}} (بدون الوسيط الثالث)؟", o: ["FALSE", "خلية فارغة", "0", "#N/A"], e: "إذا حُذف الوسيط الثالث وكان الشرط خاطئًا، تُرجع IF القيمة المنطقية FALSE. لإرجاع خلية تبدو فارغة اكتب \"\" كوسيط ثالث." },
    en: { q: "A1 = 3. What does {{=IF(A1>5,\"Yes\")}} (no third argument) return?", o: ["FALSE", "An empty cell", "0", "#N/A"], e: "When the third argument is omitted and the test is false, IF returns the logical value FALSE. To show an empty-looking cell, pass \"\" as the third argument." },
    fr: { q: "A1 = 3. Que renvoie {{=IF(A1>5,\"Yes\")}} (sans 3e argument) ?", o: ["FALSE (FAUX)", "Une cellule vide", "0", "#N/A"], e: "Si le 3e argument est omis et que le test est faux, IF renvoie la valeur logique FAUX. Pour une cellule d'apparence vide, passez \"\" en 3e argument." } },
  { level: 3,
    ar: { q: "ما عامل المقارنة «لا يساوي» في معادلات إكسل؟", o: ["<>", "!=", "=/", "><"], e: "في إكسل نكتب <> لعدم المساواة، مثل {{=IF(A1<>\"\",\"Filled\",\"Empty\")}}. الرمز != يُستخدم في لغات البرمجة لا في إكسل." },
    en: { q: "Which operator means “not equal to” in Excel formulas?", o: ["<>", "!=", "=/", "><"], e: "Excel uses <> for not equal, e.g. {{=IF(A1<>\"\",\"Filled\",\"Empty\")}}. != belongs to programming languages, not Excel." },
    fr: { q: "Quel opérateur signifie « différent de » dans les formules Excel ?", o: ["<>", "!=", "=/", "><"], e: "Excel utilise <> pour « différent de », ex. {{=IF(A1<>\"\",\"Filled\",\"Empty\")}}. != appartient aux langages de programmation, pas à Excel." } },
  { level: 3,
    ar: { q: "ماذا تحسب {{=COUNTIF(A1:A10,\">50\")}}؟", o: ["عدد الخلايا التي قيمتها أكبر من 50", "مجموع القيم الأكبر من 50", "أول قيمة أكبر من 50", "متوسط القيم"], e: "COUNTIF تعدّ الخلايا التي تحقق شرطًا واحدًا. يُكتب الشرط بين علامتي تنصيص عندما يحتوي عامل مقارنة." },
    en: { q: "What does {{=COUNTIF(A1:A10,\">50\")}} calculate?", o: ["The number of cells greater than 50", "The sum of values above 50", "The first value above 50", "The average"], e: "COUNTIF counts the cells meeting one condition. A criterion containing an operator is written in quotes." },
    fr: { q: "Que calcule {{=COUNTIF(A1:A10,\">50\")}} ?", o: ["Le nombre de cellules supérieures à 50", "La somme des valeurs au-dessus de 50", "La première valeur au-dessus de 50", "La moyenne"], e: "COUNTIF (NB.SI) compte les cellules qui remplissent une condition. Un critère contenant un opérateur s'écrit entre guillemets." } },
  { level: 3,
    ar: { q: "هل تفرّق COUNTIF بين الحروف الكبيرة والصغيرة عند عدّ النصوص (مثل «ALGER» و«alger»)؟", o: ["لا، تعدّهما معًا", "نعم، دائمًا", "فقط في الأعمدة المنسقة كنص", "فقط مع الأرقام"], e: "COUNTIF وSUMIF لا تفرّقان بين حالة الأحرف. للتمييز الدقيق تُستخدم دالة EXACT ضمن معادلة أخرى." },
    en: { q: "Is COUNTIF case-sensitive when counting text (e.g. “ALGER” vs “alger”)?", o: ["No, it counts both", "Yes, always", "Only in Text-formatted columns", "Only with numbers"], e: "COUNTIF and SUMIF are not case-sensitive. For an exact match, EXACT is used inside another formula." },
    fr: { q: "COUNTIF distingue-t-il majuscules et minuscules (ex. « ALGER » et « alger ») ?", o: ["Non, il compte les deux", "Oui, toujours", "Seulement dans les colonnes au format Texte", "Seulement avec les nombres"], e: "COUNTIF (NB.SI) et SUMIF (SOMME.SI) ne distinguent pas la casse. Pour une correspondance exacte, on utilise EXACT dans une autre formule." } },
  { level: 3,
    ar: { q: "ماذا تحسب {{=SUMIF(A2:A10,\"North\",B2:B10)}}؟", o: ["مجموع قيم B للصفوف التي يكون فيها A = North", "عدد الصفوف التي فيها North", "مجموع العمود A", "أكبر قيمة في B"], e: "SUMIF(النطاق المختبر، الشرط، نطاق الجمع): تفحص A2:A10 وتجمع القيم المقابلة في B2:B10." },
    en: { q: "What does {{=SUMIF(A2:A10,\"North\",B2:B10)}} calculate?", o: ["The sum of B values in rows where A = North", "The number of rows containing North", "The total of column A", "The largest value in B"], e: "SUMIF(range to test, criteria, sum range): it checks A2:A10 and adds the matching values from B2:B10." },
    fr: { q: "Que calcule {{=SUMIF(A2:A10,\"North\",B2:B10)}} ?", o: ["La somme des valeurs de B pour les lignes où A = North", "Le nombre de lignes contenant North", "Le total de la colonne A", "La plus grande valeur de B"], e: "SUMIF (SOMME.SI)(plage testée, critère, plage à additionner) : elle vérifie A2:A10 et additionne les valeurs correspondantes de B2:B10." } },
  { level: 3,
    ar: { q: "ما الفرق في ترتيب الوسيطات بين SUMIF وSUMIFS؟", o: ["في SUMIFS يأتي نطاق الجمع أولًا، وفي SUMIF يأتي أخيرًا", "لا فرق", "في SUMIF يأتي نطاق الجمع أولًا", "SUMIFS لا تقبل نطاق جمع"], e: "{{SUMIF(range, criteria, sum_range)}} مقابل {{SUMIFS(sum_range, criteria_range1, criteria1, ...)}}. خطأ شائع عند الانتقال بين الدالتين." },
    en: { q: "How does the argument order differ between SUMIF and SUMIFS?", o: ["In SUMIFS the sum range comes first; in SUMIF it comes last", "No difference", "In SUMIF the sum range comes first", "SUMIFS has no sum range"], e: "{{SUMIF(range, criteria, sum_range)}} versus {{SUMIFS(sum_range, criteria_range1, criteria1, ...)}} — a common mistake when switching between them." },
    fr: { q: "En quoi l'ordre des arguments diffère-t-il entre SUMIF et SUMIFS ?", o: ["Dans SUMIFS la plage à additionner vient en premier ; dans SUMIF en dernier", "Aucune différence", "Dans SUMIF la plage à additionner vient en premier", "SUMIFS n'a pas de plage à additionner"], e: "{{SUMIF(range, criteria, sum_range)}} contre {{SUMIFS(sum_range, criteria_range1, criteria1, ...)}} (SOMME.SI / SOMME.SI.ENS) — erreur fréquente quand on passe de l'une à l'autre." } },
  { level: 3,
    ar: { q: "تريد عدّ القيم في العمود A الأكبر من الرقم الموجود في الخلية D1. ما الصيغة الصحيحة؟", o: ["{{=COUNTIF(A:A,\">\"&D1)}}", "{{=COUNTIF(A:A,\">D1\")}}", "{{=COUNTIF(A:A,>D1)}}", "{{=COUNTIF(A:A,\"&>D1\")}}"], e: "يجب ربط العامل النصي \">\" بقيمة الخلية باستخدام &. أما \">D1\" فتبحث عن النص «D1» حرفيًا." },
    en: { q: "You want to count values in column A greater than the number in D1. Which formula is correct?", o: ["{{=COUNTIF(A:A,\">\"&D1)}}", "{{=COUNTIF(A:A,\">D1\")}}", "{{=COUNTIF(A:A,>D1)}}", "{{=COUNTIF(A:A,\"&>D1\")}}"], e: "The text operator \">\" must be joined to the cell's value with &. \">D1\" compares against the literal text “D1”." },
    fr: { q: "Vous voulez compter les valeurs de la colonne A supérieures au nombre en D1. Quelle formule est correcte ?", o: ["{{=COUNTIF(A:A,\">\"&D1)}}", "{{=COUNTIF(A:A,\">D1\")}}", "{{=COUNTIF(A:A,>D1)}}", "{{=COUNTIF(A:A,\"&>D1\")}}"], e: "L'opérateur texte \">\" doit être concaténé à la valeur de la cellule avec &. \">D1\" compare au texte littéral « D1 »." } },
  { level: 3,
    ar: { q: "ماذا تعدّ {{=COUNTIF(A:A,\"A*\")}}؟", o: ["الخلايا التي يبدأ نصها بالحرف A", "الخلايا التي تنتهي بـ A", "الخلايا التي تحتوي النص «A*» حرفيًا فقط", "كل الخلايا غير الفارغة"], e: "الرمز * بديل لأي عدد من الأحرف، و? بديل لحرف واحد. «A*» = يبدأ بـ A، و«*A» = ينتهي بـ A، و«*A*» = يحتوي A." },
    en: { q: "What does {{=COUNTIF(A:A,\"A*\")}} count?", o: ["Cells whose text starts with A", "Cells ending with A", "Only cells containing the literal text “A*”", "All non-empty cells"], e: "* stands for any number of characters and ? for exactly one. “A*” = starts with A, “*A” = ends with A, “*A*” = contains A." },
    fr: { q: "Que compte {{=COUNTIF(A:A,\"A*\")}} ?", o: ["Les cellules dont le texte commence par A", "Les cellules se terminant par A", "Seulement les cellules contenant le texte « A* »", "Toutes les cellules non vides"], e: "* remplace un nombre quelconque de caractères et ? un seul. « A* » = commence par A, « *A » = finit par A, « *A* » = contient A." } },
  { level: 3,
    ar: { q: "ماذا يمثل الرمز ? في شرط مثل {{=COUNTIF(A:A,\"B?D\")}}؟", o: ["حرفًا واحدًا بالضبط (مثل BAD أو BED)", "أي عدد من الأحرف", "رقمًا فقط", "علامة استفهام حرفية فقط"], e: "? بديل لحرف واحد بالضبط، فـ «B?D» تطابق BAD وBED لكن لا تطابق BREAD. للبحث عن ? أو * حرفيًا تُسبق بـ ~." },
    en: { q: "What does ? represent in a criterion such as {{=COUNTIF(A:A,\"B?D\")}}?", o: ["Exactly one character (e.g. BAD or BED)", "Any number of characters", "A digit only", "Only a literal question mark"], e: "? stands for exactly one character, so “B?D” matches BAD and BED but not BREAD. To search for a literal ? or *, precede it with ~." },
    fr: { q: "Que représente ? dans un critère comme {{=COUNTIF(A:A,\"B?D\")}} ?", o: ["Exactement un caractère (ex. BAD ou BED)", "Un nombre quelconque de caractères", "Uniquement un chiffre", "Uniquement un point d'interrogation littéral"], e: "? remplace exactement un caractère : « B?D » correspond à BAD et BED mais pas à BREAD. Pour chercher ? ou * littéralement, on les précède de ~." } },
  { level: 3,
    ar: { q: "النطاق A1:A4 يحتوي: 10، «Ali»، خلية فارغة، 7. ما نتيجة {{=COUNT(A1:A4)}}؟", o: ["2", "3", "4", "1"], e: "COUNT تعدّ الخلايا الرقمية فقط (10 و7). أما COUNTA فتعدّ كل الخلايا غير الفارغة فتُرجع 3." },
    en: { q: "A1:A4 contains: 10, “Ali”, an empty cell, 7. What does {{=COUNT(A1:A4)}} return?", o: ["2", "3", "4", "1"], e: "COUNT counts numeric cells only (10 and 7). COUNTA counts every non-empty cell and would return 3." },
    fr: { q: "A1:A4 contient : 10, « Ali », une cellule vide, 7. Que renvoie {{=COUNT(A1:A4)}} ?", o: ["2", "3", "4", "1"], e: "COUNT (NB) ne compte que les cellules numériques (10 et 7). COUNTA (NBVAL) compte toutes les cellules non vides : 3." } },
  { level: 3,
    ar: { q: "A1 = 12 وB1 = 8. ما نتيجة {{=IF(AND(A1>=10,B1>=10),\"OK\",\"No\")}}؟", o: ["No", "OK", "TRUE", "FALSE"], e: "AND تتطلب أن تكون كل الشروط صحيحة. B1>=10 خاطئ، إذن AND = FALSE فتُرجع IF «No»." },
    en: { q: "A1 = 12 and B1 = 8. What does {{=IF(AND(A1>=10,B1>=10),\"OK\",\"No\")}} return?", o: ["No", "OK", "TRUE", "FALSE"], e: "AND requires every condition to be true. B1>=10 is false, so AND = FALSE and IF returns “No”." },
    fr: { q: "A1 = 12 et B1 = 8. Que renvoie {{=IF(AND(A1>=10,B1>=10),\"OK\",\"No\")}} ?", o: ["No", "OK", "TRUE", "FALSE"], e: "AND (ET) exige que toutes les conditions soient vraies. B1>=10 est faux, donc AND = FAUX et IF renvoie « No »." } },
  { level: 3,
    ar: { q: "A1 = 5 وB1 = 15. ما نتيجة {{=OR(A1>10,B1>10)}}؟", o: ["TRUE", "FALSE", "15", "#VALUE!"], e: "OR تكفيها حالة واحدة صحيحة: B1>10 صحيح، فالنتيجة TRUE." },
    en: { q: "A1 = 5 and B1 = 15. What does {{=OR(A1>10,B1>10)}} return?", o: ["TRUE", "FALSE", "15", "#VALUE!"], e: "OR needs only one true condition: B1>10 is true, so the result is TRUE." },
    fr: { q: "A1 = 5 et B1 = 15. Que renvoie {{=OR(A1>10,B1>10)}} ?", o: ["TRUE (VRAI)", "FALSE (FAUX)", "15", "#VALUE!"], e: "OR (OU) n'a besoin que d'une condition vraie : B1>10 est vrai, donc le résultat est VRAI." } },
  { level: 3,
    ar: { q: "حددت عمود الأسماء فقط وطلبت فرزه، فظهرت رسالة «توسيع التحديد». لماذا يجب اختيارها؟", o: ["لكي تبقى بيانات كل صف مترابطة ولا تختلط الأسماء مع درجات غيرها", "لتسريع الفرز", "لحذف الصفوف الفارغة", "لا فائدة منها"], e: "فرز عمود واحد وحده يُفسد الجدول: تتغير مواضع الأسماء بينما تبقى بقية الأعمدة مكانها. «توسيع التحديد» يفرز الصفوف كاملة." },
    en: { q: "You select only the names column and sort; Excel offers “Expand the selection”. Why choose it?", o: ["So each row's data stays together and names do not get mixed with other people's scores", "To sort faster", "To delete empty rows", "It has no use"], e: "Sorting one column alone breaks the table: names move while the other columns stay put. “Expand the selection” sorts whole rows." },
    fr: { q: "Vous sélectionnez seulement la colonne des noms et triez ; Excel propose « Étendre la sélection ». Pourquoi la choisir ?", o: ["Pour que les données de chaque ligne restent ensemble et que les noms ne soient pas mélangés avec les notes d'autres personnes", "Pour trier plus vite", "Pour supprimer les lignes vides", "Elle ne sert à rien"], e: "Trier une seule colonne casse le tableau : les noms bougent mais pas les autres colonnes. « Étendre la sélection » trie les lignes entières." } },
  { level: 3,
    ar: { q: "كيف تفرز البيانات حسب «المنطقة» ثم حسب «المبيعات» داخل كل منطقة؟", o: ["بيانات ← فرز ← إضافة مستوى", "فرز العمودين كلًّا على حدة بسرعة", "باستخدام التصفية فقط", "هذا غير ممكن"], e: "نافذة «فرز» تسمح بعدة مستويات: المستوى الأول المنطقة، والثاني المبيعات (من الأكبر إلى الأصغر مثلًا)." },
    en: { q: "How do you sort by Region and then by Sales within each region?", o: ["Data → Sort → Add Level", "Quickly sort each column separately", "Using Filter only", "It is not possible"], e: "The Sort dialog supports several levels: first level Region, second level Sales (e.g. largest to smallest)." },
    fr: { q: "Comment trier par Région puis par Ventes à l'intérieur de chaque région ?", o: ["Données → Trier → Ajouter un niveau", "Trier rapidement chaque colonne séparément", "Uniquement avec le filtre", "Ce n'est pas possible"], e: "La boîte Trier accepte plusieurs niveaux : 1er niveau Région, 2e niveau Ventes (par ex. du plus grand au plus petit)." } },
  { level: 3,
    ar: { q: "ماذا يحدث للصفوف التي لا تطابق شرط «التصفية» (Filter)؟", o: ["تُخفى مؤقتًا ولا تُحذف", "تُحذف نهائيًا", "تنتقل إلى ورقة أخرى", "تُلوَّن بالأحمر"], e: "التصفية تُخفي الصفوف غير المطابقة فقط، وتعود كلها عند مسح عامل التصفية. لاحظ أن أرقام الصفوف الظاهرة تصبح باللون الأزرق." },
    en: { q: "What happens to rows that do not match a Filter condition?", o: ["They are temporarily hidden, not deleted", "They are permanently deleted", "They move to another sheet", "They turn red"], e: "Filtering only hides non-matching rows; they all come back when the filter is cleared. Notice the visible row numbers turn blue." },
    fr: { q: "Que deviennent les lignes qui ne correspondent pas à un filtre ?", o: ["Elles sont masquées temporairement, pas supprimées", "Elles sont supprimées définitivement", "Elles passent sur une autre feuille", "Elles deviennent rouges"], e: "Le filtre masque seulement les lignes non conformes ; elles réapparaissent quand on efface le filtre. Les numéros des lignes visibles passent en bleu." } },
  { level: 3,
    ar: { q: "ما الاختصار الذي يُفعّل أو يُلغي أزرار التصفية في رؤوس الجدول؟", o: ["Ctrl+Shift+L", "Ctrl+F", "Alt+F", "Ctrl+L+F"], e: "Ctrl+Shift+L يضيف أسهم التصفية إلى صف العناوين أو يزيلها. (Ctrl+F للبحث)." },
    en: { q: "Which shortcut turns the filter buttons in the header row on or off?", o: ["Ctrl+Shift+L", "Ctrl+F", "Alt+F", "Ctrl+L+F"], e: "Ctrl+Shift+L adds or removes the filter arrows in the header row. (Ctrl+F is Find.)" },
    fr: { q: "Quel raccourci active ou désactive les boutons de filtre de la ligne d'en-tête ?", o: ["Ctrl+Maj+L", "Ctrl+F", "Alt+F", "Ctrl+L+F"], e: "Ctrl+Maj+L ajoute ou retire les flèches de filtre de la ligne d'en-tête. (Ctrl+F sert à Rechercher.)" } },
  { level: 3,
    ar: { q: "بعد تصفية جدول، أي دالة تجمع الصفوف الظاهرة فقط؟", o: ["{{=SUBTOTAL(109,B2:B100)}}", "{{=SUM(B2:B100)}}", "{{=SUMIF(B2:B100,\"<>\")}}", "{{=TOTAL(B2:B100)}}"], e: "SUM تجمع كل الصفوف حتى المخفية، أما SUBTOTAL (و AGGREGATE) فتتجاهل الصفوف المخفية بالتصفية. الرمز 109 يعني «جمع» مع تجاهل المخفي يدويًا أيضًا." },
    en: { q: "After filtering a table, which function sums only the visible rows?", o: ["{{=SUBTOTAL(109,B2:B100)}}", "{{=SUM(B2:B100)}}", "{{=SUMIF(B2:B100,\"<>\")}}", "{{=TOTAL(B2:B100)}}"], e: "SUM adds every row, even hidden ones; SUBTOTAL (and AGGREGATE) ignore rows hidden by a filter. Code 109 means “sum”, also ignoring manually hidden rows." },
    fr: { q: "Après avoir filtré un tableau, quelle fonction additionne uniquement les lignes visibles ?", o: ["{{=SUBTOTAL(109,B2:B100)}}", "{{=SUM(B2:B100)}}", "{{=SUMIF(B2:B100,\"<>\")}}", "{{=TOTAL(B2:B100)}}"], e: "SUM additionne toutes les lignes, même masquées ; SUBTOTAL (SOUS.TOTAL) et AGGREGATE ignorent les lignes masquées par un filtre. Le code 109 = « somme », en ignorant aussi les lignes masquées manuellement." } },
  { level: 3,
    ar: { q: "ماذا يفعل عامل تصفية الأرقام «أعلى 10» (Top 10)؟", o: ["يعرض أعلى (أو أدنى) N عنصر أو نسبة تختارها، وليس بالضرورة 10", "يعرض أول 10 صفوف في الجدول", "يحذف كل القيم عدا 10", "يرتب البيانات فقط"], e: "رغم اسمه، يمكنك اختيار أي عدد (مثلًا أعلى 3) أو نسبة مئوية، ومن الأعلى أو الأدنى." },
    en: { q: "What does the “Top 10” number filter do?", o: ["Shows the top (or bottom) N items or percent you choose — not necessarily 10", "Shows the first 10 rows of the table", "Deletes all values except 10", "Only sorts the data"], e: "Despite its name you can choose any number (e.g. top 3) or a percentage, from the top or the bottom." },
    fr: { q: "Que fait le filtre numérique « 10 premiers » ?", o: ["Il affiche les N premiers (ou derniers) éléments ou pourcentages choisis — pas forcément 10", "Il affiche les 10 premières lignes du tableau", "Il supprime toutes les valeurs sauf 10", "Il trie seulement les données"], e: "Malgré son nom, on peut choisir n'importe quel nombre (ex. 3 premiers) ou un pourcentage, en haut ou en bas du classement." } },
  { level: 3,
    ar: { q: "هل يمكن فرز البيانات حسب لون الخلية في إكسل؟", o: ["نعم، من نافذة «فرز» باختيار «لون الخلية» في خانة «الفرز حسب»", "لا، أبدًا", "فقط باستخدام VBA", "فقط بعد تحويل البيانات إلى PDF"], e: "يمكن الفرز (والتصفية) حسب قيم الخلايا أو لون الخلية أو لون الخط أو أيقونة التنسيق الشرطي." },
    en: { q: "Can Excel sort data by cell colour?", o: ["Yes — in the Sort dialog choose “Cell Color” under Sort On", "No, never", "Only with VBA", "Only after converting to PDF"], e: "You can sort (and filter) by cell values, cell colour, font colour, or conditional-formatting icon." },
    fr: { q: "Excel peut-il trier les données par couleur de cellule ?", o: ["Oui — dans Trier, choisir « Couleur de cellule » sous « Trier sur »", "Non, jamais", "Seulement avec VBA", "Seulement après conversion en PDF"], e: "On peut trier (et filtrer) par valeurs, couleur de cellule, couleur de police ou icône de mise en forme conditionnelle." } },
  { level: 3,
    ar: { q: "كيف تفرز عمودًا يحتوي «منخفض، متوسط، مرتفع» بهذا الترتيب المنطقي لا أبجديًا؟", o: ["بإنشاء «قائمة مخصصة» واختيارها في خانة «الترتيب» داخل نافذة الفرز", "بالفرز من A إلى Z", "بالفرز من Z إلى A", "هذا مستحيل"], e: "الفرز الأبجدي سيعطي ترتيبًا غير منطقي. القوائم المخصصة تحدد ترتيبك الخاص للفرز وللتعبئة التلقائية أيضًا." },
    en: { q: "How do you sort a column containing “Low, Medium, High” in that logical order rather than alphabetically?", o: ["Create a Custom List and choose it under Order in the Sort dialog", "Sort A to Z", "Sort Z to A", "It is impossible"], e: "Alphabetical sorting gives an illogical order. Custom Lists define your own order for sorting and for AutoFill too." },
    fr: { q: "Comment trier une colonne « Faible, Moyen, Élevé » dans cet ordre logique plutôt qu'alphabétique ?", o: ["Créer une liste personnalisée et la choisir sous « Ordre » dans la boîte Trier", "Trier de A à Z", "Trier de Z à A", "C'est impossible"], e: "Le tri alphabétique donne un ordre illogique. Les listes personnalisées définissent votre propre ordre, pour le tri comme pour la recopie automatique." } },
  { level: 3,
    ar: { q: "كيف تشير في معادلة إلى الخلية A1 الموجودة في ورقة اسمها Sheet2؟", o: ["{{=Sheet2!A1}}", "{{=Sheet2.A1}}", "{{=Sheet2:A1}}", "{{=[Sheet2]A1}}"], e: "علامة التعجب ! تفصل اسم الورقة عن الخلية. إذا احتوى اسم الورقة مسافات يوضع بين علامتي اقتباس مفردتين: {{='Sales 2026'!A1}}." },
    en: { q: "How do you refer to cell A1 on a sheet named Sheet2 in a formula?", o: ["{{=Sheet2!A1}}", "{{=Sheet2.A1}}", "{{=Sheet2:A1}}", "{{=[Sheet2]A1}}"], e: "The exclamation mark ! separates the sheet name from the cell. If the name contains spaces, wrap it in single quotes: {{='Sales 2026'!A1}}." },
    fr: { q: "Comment faire référence dans une formule à la cellule A1 d'une feuille nommée Sheet2 ?", o: ["{{=Sheet2!A1}}", "{{=Sheet2.A1}}", "{{=Sheet2:A1}}", "{{=[Sheet2]A1}}"], e: "Le point d'exclamation ! sépare le nom de la feuille de la cellule. Si le nom contient des espaces, on l'entoure d'apostrophes : {{='Ventes 2026'!A1}}." } },
  { level: 3,
    ar: { q: "نسبة الضريبة موجودة في E1، والأسعار في B2:B20. ما المعادلة في C2 التي يمكن نسخها للأسفل وتبقى مرتبطة بالخلية E1؟", o: ["{{=B2*$E$1}}", "{{=B2*E1}}", "{{=$B$2*E1}}", "{{=B$2*E$1}}"], e: "E1 يجب أن يكون مطلقًا ($E$1) حتى لا يتحول إلى E2 وE3… عند النسخ، بينما B2 يبقى نسبيًا ليتغير مع كل صف." },
    en: { q: "The tax rate is in E1 and prices are in B2:B20. Which formula in C2 can be copied down and still point to E1?", o: ["{{=B2*$E$1}}", "{{=B2*E1}}", "{{=$B$2*E1}}", "{{=B$2*E$1}}"], e: "E1 must be absolute ($E$1) so it does not become E2, E3… when copied, while B2 stays relative to follow each row." },
    fr: { q: "Le taux de taxe est en E1 et les prix en B2:B20. Quelle formule en C2 peut être recopiée vers le bas tout en pointant vers E1 ?", o: ["{{=B2*$E$1}}", "{{=B2*E1}}", "{{=$B$2*E1}}", "{{=B$2*E$1}}"], e: "E1 doit être absolue ($E$1) pour ne pas devenir E2, E3… à la recopie, tandis que B2 reste relative pour suivre chaque ligne." } },
  /* ===================== LEVEL 4 — lookups, INDEX/MATCH, conditional formatting, charts, validation ===================== */
  { level: 4,
    ar: { q: "ما الترتيب الصحيح لوسيطات VLOOKUP؟", o: ["القيمة المبحوث عنها، الجدول، رقم العمود، نوع المطابقة", "الجدول، القيمة المبحوث عنها، رقم العمود، نوع المطابقة", "رقم العمود، الجدول، القيمة المبحوث عنها", "القيمة المبحوث عنها، عمود البحث، عمود النتيجة"], e: "{{VLOOKUP(lookup_value, table_array, col_index_num, [range_lookup])}}. الخيار الأخير يشبه XLOOKUP لا VLOOKUP." },
    en: { q: "What is the correct argument order of VLOOKUP?", o: ["Lookup value, table, column number, match type", "Table, lookup value, column number, match type", "Column number, table, lookup value", "Lookup value, lookup column, return column"], e: "{{VLOOKUP(lookup_value, table_array, col_index_num, [range_lookup])}}. The last option describes XLOOKUP, not VLOOKUP." },
    fr: { q: "Quel est l'ordre correct des arguments de VLOOKUP (RECHERCHEV) ?", o: ["Valeur cherchée, tableau, n° de colonne, type de correspondance", "Tableau, valeur cherchée, n° de colonne, type de correspondance", "N° de colonne, tableau, valeur cherchée", "Valeur cherchée, colonne de recherche, colonne de résultat"], e: "{{VLOOKUP(lookup_value, table_array, col_index_num, [range_lookup])}}. La dernière option décrit XLOOKUP (RECHERCHEX), pas VLOOKUP." } },
  { level: 4,
    ar: { q: "ماذا يعني وضع FALSE (أو 0) كوسيط رابع في VLOOKUP؟", o: ["البحث عن تطابق تام", "البحث عن تطابق تقريبي", "البحث من الأسفل إلى الأعلى", "تجاهل الأخطاء"], e: "FALSE = تطابق تام، وهو المطلوب في أغلب الحالات (رموز المنتجات، الأسماء…). إن لم توجد القيمة تُرجع #N/A." },
    en: { q: "What does FALSE (or 0) as VLOOKUP's fourth argument mean?", o: ["Exact match", "Approximate match", "Search from bottom to top", "Ignore errors"], e: "FALSE = exact match, which is what you need most of the time (product codes, names…). If the value is not found it returns #N/A." },
    fr: { q: "Que signifie FALSE (ou 0) en 4e argument de VLOOKUP ?", o: ["Correspondance exacte", "Correspondance approximative", "Recherche du bas vers le haut", "Ignorer les erreurs"], e: "FAUX = correspondance exacte, ce dont on a besoin la plupart du temps (codes produits, noms…). Si la valeur est introuvable : #N/A." } },
  { level: 4,
    ar: { q: "ما القيد الأساسي في VLOOKUP؟", o: ["يجب أن تكون القيمة المبحوث عنها في العمود الأول من الجدول، فلا تستطيع إرجاع عمود على يسارها", "لا تعمل مع النصوص", "لا تقبل أكثر من 100 صف", "لا تعمل بين ورقتين"], e: "VLOOKUP تبحث دائمًا في العمود الأول من النطاق وتُرجع من عمود على يمينه. لتجاوز ذلك استخدم XLOOKUP أو INDEX/MATCH." },
    en: { q: "What is VLOOKUP's main limitation?", o: ["The lookup value must be in the first column of the table, so it cannot return a column to its left", "It does not work with text", "It cannot handle more than 100 rows", "It does not work across sheets"], e: "VLOOKUP always searches the first column of the range and returns from a column to its right. Use XLOOKUP or INDEX/MATCH to get around this." },
    fr: { q: "Quelle est la principale limite de VLOOKUP ?", o: ["La valeur cherchée doit être dans la 1re colonne du tableau ; elle ne peut pas renvoyer une colonne située à sa gauche", "Elle ne fonctionne pas avec du texte", "Elle ne gère pas plus de 100 lignes", "Elle ne fonctionne pas entre feuilles"], e: "VLOOKUP cherche toujours dans la 1re colonne de la plage et renvoie une colonne à sa droite. XLOOKUP ou INDEX/MATCH lèvent cette limite." } },
  { level: 4,
    ar: { q: "معادلة VLOOKUP بتطابق تام تُرجع #N/A. ما السبب الأكثر احتمالًا؟", o: ["القيمة المبحوث عنها غير موجودة في العمود الأول (أو تختلف بمسافة زائدة أو بنوعها نص/رقم)", "رقم العمود أكبر من اللازم", "الملف غير محفوظ", "الجدول مرتب"], e: "#N/A تعني «غير متوفر». من الأسباب الخفية: مسافات زائدة (عالجها بـ TRIM) أو رقم مخزن كنص. أما رقم العمود الزائد فيعطي #REF!." },
    en: { q: "An exact-match VLOOKUP returns #N/A. What is the most likely cause?", o: ["The lookup value is not in the first column (or differs by an extra space or by text/number type)", "The column number is too large", "The file is not saved", "The table is sorted"], e: "#N/A means “not available”. Hidden causes include extra spaces (fix with TRIM) or a number stored as text. A column number that is too large gives #REF!." },
    fr: { q: "Un VLOOKUP en correspondance exacte renvoie #N/A. Quelle est la cause la plus probable ?", o: ["La valeur cherchée n'est pas dans la 1re colonne (ou diffère par un espace en trop ou par le type texte/nombre)", "Le n° de colonne est trop grand", "Le fichier n'est pas enregistré", "Le tableau est trié"], e: "#N/A signifie « non disponible ». Causes cachées : espaces en trop (corrigez avec TRIM / SUPPRESPACE) ou nombre stocké en texte. Un n° de colonne trop grand donne #REF!." } },
  { level: 4,
    ar: { q: "إذا حذفت الوسيط الرابع من VLOOKUP، ما نوع البحث الافتراضي وما شرطه؟", o: ["تطابق تقريبي (TRUE)، ويتطلب أن يكون العمود الأول مرتبًا تصاعديًا", "تطابق تام دائمًا", "تطابق تقريبي ولا يحتاج أي ترتيب", "تُرجع خطأ لأن الوسيط إلزامي"], e: "الافتراضي TRUE (تقريبي)، وهو مفيد لجداول الشرائح (مثل شرائح الضريبة أو التقديرات) بشرط ترتيب العمود الأول تصاعديًا، وإلا كانت النتائج خاطئة بصمت." },
    en: { q: "If you omit VLOOKUP's fourth argument, what is the default lookup type and its requirement?", o: ["Approximate match (TRUE); the first column must be sorted ascending", "Always exact match", "Approximate match with no sorting needed", "An error, because the argument is mandatory"], e: "The default is TRUE (approximate), useful for bracket tables (tax bands, grades) provided the first column is sorted ascending — otherwise results are silently wrong." },
    fr: { q: "Si on omet le 4e argument de VLOOKUP, quel est le type de recherche par défaut et sa condition ?", o: ["Correspondance approximative (VRAI) ; la 1re colonne doit être triée par ordre croissant", "Toujours une correspondance exacte", "Approximative sans besoin de tri", "Une erreur, car l'argument est obligatoire"], e: "Par défaut VRAI (approximative), utile pour les barèmes (tranches d'impôt, mentions) à condition que la 1re colonne soit triée par ordre croissant — sinon les résultats sont faux sans avertissement." } },
  { level: 4,
    ar: { q: "من أي عمود تُرجع {{=VLOOKUP(\"P02\",B2:E50,3,FALSE)}} النتيجة؟", o: ["العمود D", "العمود C", "العمود E", "الصف 3"], e: "رقم العمود يُحسب داخل النطاق لا في الورقة: B هو الأول، C الثاني، D الثالث." },
    en: { q: "From which column does {{=VLOOKUP(\"P02\",B2:E50,3,FALSE)}} return its result?", o: ["Column D", "Column C", "Column E", "Row 3"], e: "The column number counts within the range, not the sheet: B is 1st, C is 2nd, D is 3rd." },
    fr: { q: "De quelle colonne {{=VLOOKUP(\"P02\",B2:E50,3,FALSE)}} renvoie-t-elle le résultat ?", o: ["La colonne D", "La colonne C", "La colonne E", "La ligne 3"], e: "Le n° de colonne se compte dans la plage, pas dans la feuille : B est la 1re, C la 2e, D la 3e." } },
  { level: 4,
    ar: { q: "ما الخطر الرئيسي في كتابة رقم العمود يدويًا داخل VLOOKUP (مثل 3)؟", o: ["إدراج أو حذف عمود داخل الجدول يجعلها تُرجع عمودًا خاطئًا دون أي رسالة خطأ", "تصبح المعادلة أبطأ بكثير", "لا يمكن نسخ المعادلة", "تتحول النتيجة إلى نص"], e: "الرقم 3 لا يتغير تلقائيًا عند تعديل بنية الجدول. الحلول: XLOOKUP، أو INDEX/MATCH، أو حساب رقم العمود بـ MATCH." },
    en: { q: "What is the main risk of typing VLOOKUP's column number by hand (e.g. 3)?", o: ["Inserting or deleting a column in the table makes it return the wrong column with no error", "The formula becomes much slower", "The formula cannot be copied", "The result turns into text"], e: "The 3 does not update when the table structure changes. Solutions: XLOOKUP, INDEX/MATCH, or computing the column number with MATCH." },
    fr: { q: "Quel est le principal risque de taper à la main le n° de colonne de VLOOKUP (ex. 3) ?", o: ["Insérer ou supprimer une colonne dans le tableau lui fait renvoyer la mauvaise colonne sans erreur", "La formule devient beaucoup plus lente", "La formule ne peut pas être recopiée", "Le résultat devient du texte"], e: "Le 3 ne s'adapte pas quand la structure change. Solutions : XLOOKUP, INDEX/MATCH, ou calculer le n° de colonne avec MATCH (EQUIV)." } },
  { level: 4,
    ar: { q: "ما الترتيب الصحيح لأول ثلاثة وسيطات في XLOOKUP؟", o: ["القيمة المبحوث عنها، نطاق البحث، نطاق الإرجاع", "نطاق البحث، القيمة المبحوث عنها، نطاق الإرجاع", "القيمة المبحوث عنها، الجدول، رقم العمود", "نطاق الإرجاع، نطاق البحث، القيمة المبحوث عنها"], e: "{{XLOOKUP(lookup_value, lookup_array, return_array, [if_not_found], [match_mode], [search_mode])}}." },
    en: { q: "What is the correct order of XLOOKUP's first three arguments?", o: ["Lookup value, lookup array, return array", "Lookup array, lookup value, return array", "Lookup value, table, column number", "Return array, lookup array, lookup value"], e: "{{XLOOKUP(lookup_value, lookup_array, return_array, [if_not_found], [match_mode], [search_mode])}}." },
    fr: { q: "Quel est l'ordre correct des trois premiers arguments de XLOOKUP (RECHERCHEX) ?", o: ["Valeur cherchée, plage de recherche, plage de résultats", "Plage de recherche, valeur cherchée, plage de résultats", "Valeur cherchée, tableau, n° de colonne", "Plage de résultats, plage de recherche, valeur cherchée"], e: "{{XLOOKUP(lookup_value, lookup_array, return_array, [if_not_found], [match_mode], [search_mode])}}." } },
  { level: 4,
    ar: { q: "ما نوع المطابقة الافتراضي في XLOOKUP إذا لم تحدده؟", o: ["تطابق تام", "تطابق تقريبي", "أقرب قيمة أكبر", "مطابقة بأحرف البدل"], e: "بعكس VLOOKUP، الافتراضي في XLOOKUP هو التطابق التام (match_mode = 0)، وهذا يقلل الأخطاء الصامتة." },
    en: { q: "What is XLOOKUP's default match type when you do not specify it?", o: ["Exact match", "Approximate match", "Next larger value", "Wildcard match"], e: "Unlike VLOOKUP, XLOOKUP defaults to exact match (match_mode = 0), which reduces silent errors." },
    fr: { q: "Quel est le type de correspondance par défaut de XLOOKUP si on ne le précise pas ?", o: ["Correspondance exacte", "Correspondance approximative", "Valeur immédiatement supérieure", "Correspondance avec caractères génériques"], e: "Contrairement à VLOOKUP, XLOOKUP est en correspondance exacte par défaut (match_mode = 0), ce qui limite les erreurs silencieuses." } },
  { level: 4,
    ar: { q: "ماذا تُرجع {{=XLOOKUP(A2,D:D,E:E,\"Not found\")}} إذا لم توجد قيمة A2 في العمود D؟", o: ["النص «Not found» بدل الخطأ", "#N/A", "0", "أول قيمة في العمود E"], e: "الوسيط الرابع if_not_found يحدد ما يظهر عند عدم وجود القيمة، فلا حاجة لتغليف المعادلة بـ IFERROR." },
    en: { q: "What does {{=XLOOKUP(A2,D:D,E:E,\"Not found\")}} return if A2's value is not in column D?", o: ["The text “Not found” instead of an error", "#N/A", "0", "The first value in column E"], e: "The fourth argument, if_not_found, defines what to show when nothing matches, so there is no need to wrap it in IFERROR." },
    fr: { q: "Que renvoie {{=XLOOKUP(A2,D:D,E:E,\"Not found\")}} si la valeur de A2 n'est pas dans la colonne D ?", o: ["Le texte « Not found » au lieu d'une erreur", "#N/A", "0", "La première valeur de la colonne E"], e: "Le 4e argument, if_not_found, définit ce qui s'affiche en l'absence de correspondance : inutile d'ajouter IFERROR (SIERREUR)." } },
  { level: 4,
    ar: { q: "في أي إصدارات إكسل تتوفر الدالة XLOOKUP؟", o: ["Microsoft 365 وإكسل 2021 وما بعده وإكسل للويب", "كل الإصدارات منذ 2007", "إكسل 2010 فقط", "إكسل 2016 و2019 فقط"], e: "XLOOKUP غير موجودة في 2016 و2019؛ فتح ملف يستخدمها في إصدار قديم يُظهر الخطأ #NAME?. في هذه الحالة استخدم INDEX/MATCH." },
    en: { q: "In which Excel versions is XLOOKUP available?", o: ["Microsoft 365, Excel 2021 and later, and Excel for the web", "Every version since 2007", "Excel 2010 only", "Excel 2016 and 2019 only"], e: "XLOOKUP does not exist in 2016 or 2019; opening a file that uses it in an older version shows #NAME?. Use INDEX/MATCH there." },
    fr: { q: "Dans quelles versions d'Excel XLOOKUP est-elle disponible ?", o: ["Microsoft 365, Excel 2021 et ultérieur, et Excel pour le web", "Toutes les versions depuis 2007", "Excel 2010 uniquement", "Excel 2016 et 2019 uniquement"], e: "XLOOKUP n'existe pas dans 2016 ni 2019 ; un fichier qui l'utilise y affiche #NOM?. Dans ce cas, utilisez INDEX/MATCH (INDEX/EQUIV)." } },
  { level: 4,
    ar: { q: "هل تستطيع XLOOKUP إرجاع قيمة من عمود يقع يسار عمود البحث؟", o: ["نعم، لأن نطاق الإرجاع مستقل عن نطاق البحث", "لا، مثل VLOOKUP", "فقط إذا كانت البيانات مرتبة", "فقط في جداول Excel المنسقة"], e: "في XLOOKUP تختار عمود البحث وعمود الإرجاع بشكل منفصل، فيمكن أن يكون الإرجاع يمينًا أو يسارًا." },
    en: { q: "Can XLOOKUP return a value from a column to the left of the lookup column?", o: ["Yes, because the return array is independent of the lookup array", "No, just like VLOOKUP", "Only if the data is sorted", "Only in formatted Excel Tables"], e: "In XLOOKUP you pick the lookup column and the return column separately, so the return column can be to the right or the left." },
    fr: { q: "XLOOKUP peut-elle renvoyer une valeur d'une colonne située à gauche de la colonne de recherche ?", o: ["Oui, car la plage de résultats est indépendante de la plage de recherche", "Non, comme VLOOKUP", "Seulement si les données sont triées", "Seulement dans les tableaux Excel mis en forme"], e: "Avec XLOOKUP, on choisit séparément la colonne de recherche et celle du résultat : celle-ci peut être à droite comme à gauche." } },
  { level: 4,
    ar: { q: "ما فائدة وضع -1 في الوسيط search_mode للدالة XLOOKUP؟", o: ["البحث من آخر صف إلى أوله لإيجاد آخر ظهور للقيمة", "إرجاع قيمة سالبة", "البحث التقريبي", "تجاهل الحالة"], e: "search_mode = -1 يبدأ البحث من النهاية، وهو مفيد لإيجاد آخر عملية أو آخر سعر مسجل لمنتج." },
    en: { q: "What is the benefit of -1 in XLOOKUP's search_mode argument?", o: ["Searching from the last row to the first to find the last occurrence", "Returning a negative value", "Approximate lookup", "Ignoring case"], e: "search_mode = -1 starts at the end — useful to find the latest transaction or last recorded price of a product." },
    fr: { q: "À quoi sert -1 dans l'argument search_mode de XLOOKUP ?", o: ["Chercher de la dernière ligne à la première pour trouver la dernière occurrence", "Renvoyer une valeur négative", "Faire une recherche approximative", "Ignorer la casse"], e: "search_mode = -1 commence par la fin — pratique pour trouver la dernière transaction ou le dernier prix enregistré d'un produit." } },
  { level: 4,
    ar: { q: "ما نتيجة {{=INDEX(A1:C10,4,2)}}؟", o: ["قيمة الخلية B4", "قيمة الخلية D2", "قيمة الخلية C4", "قيمة الخلية B2"], e: "INDEX(النطاق، رقم الصف، رقم العمود): الصف الرابع والعمود الثاني داخل A1:C10 هو B4." },
    en: { q: "What does {{=INDEX(A1:C10,4,2)}} return?", o: ["The value of cell B4", "The value of cell D2", "The value of cell C4", "The value of cell B2"], e: "INDEX(range, row number, column number): the 4th row and 2nd column inside A1:C10 is B4." },
    fr: { q: "Que renvoie {{=INDEX(A1:C10,4,2)}} ?", o: ["La valeur de la cellule B4", "La valeur de la cellule D2", "La valeur de la cellule C4", "La valeur de la cellule B2"], e: "INDEX(plage, n° de ligne, n° de colonne) : la 4e ligne et la 2e colonne de A1:C10, c'est B4." } },
  { level: 4,
    ar: { q: "ماذا تُرجع {{=MATCH(\"Ali\",A1:A10,0)}}؟", o: ["رقم موضع «Ali» داخل النطاق (مثلًا 3)", "القيمة «Ali» نفسها", "عنوان الخلية مثل A3", "TRUE أو FALSE"], e: "MATCH تُرجع الموضع النسبي داخل النطاق، والوسيط 0 يعني تطابقًا تامًا. لهذا تُستخدم كثيرًا داخل INDEX." },
    en: { q: "What does {{=MATCH(\"Ali\",A1:A10,0)}} return?", o: ["The position of “Ali” within the range (e.g. 3)", "The value “Ali” itself", "The cell address, e.g. A3", "TRUE or FALSE"], e: "MATCH returns the relative position in the range; 0 means exact match. That is why it is often used inside INDEX." },
    fr: { q: "Que renvoie {{=MATCH(\"Ali\",A1:A10,0)}} ?", o: ["La position de « Ali » dans la plage (ex. 3)", "La valeur « Ali » elle-même", "L'adresse de la cellule, ex. A3", "VRAI ou FAUX"], e: "MATCH (EQUIV) renvoie la position relative dans la plage ; 0 = correspondance exacte. C'est pourquoi on l'utilise souvent dans INDEX." } },
  { level: 4,
    ar: { q: "ماذا تفعل المعادلة {{=INDEX(C2:C100,MATCH(F1,A2:A100,0))}}؟", o: ["تبحث عن F1 في العمود A وتُرجع القيمة المقابلة من العمود C", "تجمع العمود C", "تبحث عن F1 في العمود C", "تُرجع رقم الصف فقط"], e: "MATCH تحدد رقم الصف الذي فيه F1 داخل A2:A100، ثم INDEX تُرجع القيمة في نفس الموضع من C2:C100." },
    en: { q: "What does {{=INDEX(C2:C100,MATCH(F1,A2:A100,0))}} do?", o: ["Finds F1 in column A and returns the matching value from column C", "Sums column C", "Searches for F1 in column C", "Returns only the row number"], e: "MATCH finds which row of A2:A100 holds F1, then INDEX returns the value at the same position in C2:C100." },
    fr: { q: "Que fait {{=INDEX(C2:C100,MATCH(F1,A2:A100,0))}} ?", o: ["Elle cherche F1 dans la colonne A et renvoie la valeur correspondante de la colonne C", "Elle additionne la colonne C", "Elle cherche F1 dans la colonne C", "Elle renvoie seulement le n° de ligne"], e: "MATCH trouve la ligne de A2:A100 contenant F1, puis INDEX renvoie la valeur à la même position dans C2:C100." } },
  { level: 4,
    ar: { q: "ما الميزة الأهم لتركيبة INDEX/MATCH مقارنة بـ VLOOKUP؟", o: ["البحث في أي اتجاه وعدم التأثر بإدراج الأعمدة، مع العمل في الإصدارات القديمة", "أنها أقصر في الكتابة", "أنها تلوّن النتائج", "أنها لا تحتاج تطابقًا تامًا أبدًا"], e: "INDEX/MATCH تفصل عمود البحث عن عمود النتيجة، فتبحث يمينًا أو يسارًا ولا تنكسر عند تغيير ترتيب الأعمدة، وتعمل في كل الإصدارات." },
    en: { q: "What is the main advantage of INDEX/MATCH over VLOOKUP?", o: ["It looks up in any direction, is not broken by inserted columns, and works in old versions", "It is shorter to type", "It colours the results", "It never needs an exact match"], e: "INDEX/MATCH separates the lookup column from the result column, so it can look left or right, does not break when columns are rearranged, and works in every version." },
    fr: { q: "Quel est le principal avantage d'INDEX/MATCH sur VLOOKUP ?", o: ["Recherche dans tous les sens, insensible aux colonnes insérées, et compatible avec les anciennes versions", "Elle est plus courte à écrire", "Elle colore les résultats", "Elle n'a jamais besoin de correspondance exacte"], e: "INDEX/MATCH sépare la colonne de recherche de celle du résultat : elle cherche à gauche comme à droite, ne casse pas quand on réorganise les colonnes, et marche dans toutes les versions." } },
  { level: 4,
    ar: { q: "ما «التنسيق الشرطي» (Conditional Formatting)؟", o: ["تنسيق يُطبَّق تلقائيًا على الخلايا حسب قيمها أو حسب قاعدة تحددها", "تنسيق لا يمكن تغييره", "تنسيق خاص بالطباعة", "نسخ التنسيق من ملف آخر"], e: "مثال: تلوين الدرجات الأقل من 10 بالأحمر. عند تغير القيمة يتغير التنسيق تلقائيًا." },
    en: { q: "What is Conditional Formatting?", o: ["Formatting applied automatically to cells based on their values or a rule you define", "Formatting that cannot be changed", "Print-only formatting", "Copying formatting from another file"], e: "Example: colour marks below 10 in red. When the value changes, the formatting updates automatically." },
    fr: { q: "Qu'est-ce que la mise en forme conditionnelle ?", o: ["Une mise en forme appliquée automatiquement aux cellules selon leurs valeurs ou une règle définie", "Une mise en forme non modifiable", "Une mise en forme réservée à l'impression", "La copie de la mise en forme d'un autre fichier"], e: "Exemple : colorer en rouge les notes inférieures à 10. Quand la valeur change, la mise en forme suit automatiquement." } },
  { level: 4,
    ar: { q: "حددت A2:F100 وتريد تلوين الصف كاملًا عندما تكون الحالة في العمود D هي «Late». ما صيغة قاعدة التنسيق الشرطي الصحيحة؟", o: ["{{=$D2=\"Late\"}}", "{{=D2=\"Late\"}}", "{{=$D$2=\"Late\"}}", "{{=D$2=\"Late\"}}"], e: "نثبّت العمود D ($D) حتى تفحص كل الخلايا في الصف العمود نفسه، ونترك الصف نسبيًا (2) ليتغير مع كل صف. $D$2 كان سيفحص خلية واحدة لكل الجدول." },
    en: { q: "You selected A2:F100 and want to colour the whole row when the status in column D is “Late”. Which conditional-formatting formula is correct?", o: ["{{=$D2=\"Late\"}}", "{{=D2=\"Late\"}}", "{{=$D$2=\"Late\"}}", "{{=D$2=\"Late\"}}"], e: "Lock column D ($D) so every cell in the row checks the same column, and keep the row relative (2) so it changes with each row. $D$2 would test a single cell for the whole table." },
    fr: { q: "Vous avez sélectionné A2:F100 et voulez colorer toute la ligne quand le statut en colonne D est « Late ». Quelle formule de mise en forme conditionnelle est correcte ?", o: ["{{=$D2=\"Late\"}}", "{{=D2=\"Late\"}}", "{{=$D$2=\"Late\"}}", "{{=D$2=\"Late\"}}"], e: "On bloque la colonne D ($D) pour que chaque cellule de la ligne teste la même colonne, et on laisse la ligne relative (2) pour qu'elle suive chaque ligne. $D$2 testerait une seule cellule pour tout le tableau." } },
  { level: 4,
    ar: { q: "ماذا تعرض «أشرطة البيانات» (Data Bars) في التنسيق الشرطي؟", o: ["شريطًا ملونًا داخل كل خلية يتناسب طوله مع قيمتها", "مخططًا منفصلًا في ورقة جديدة", "سهمًا يشير لأعلى أو لأسفل فقط", "حدودًا حول الخلايا"], e: "أشرطة البيانات تعطي مقارنة بصرية سريعة بين القيم دون إنشاء مخطط. أما الأسهم فهي من «مجموعات الأيقونات»." },
    en: { q: "What do Data Bars show in conditional formatting?", o: ["A coloured bar inside each cell whose length is proportional to its value", "A separate chart on a new sheet", "Only an up or down arrow", "Borders around the cells"], e: "Data bars give a quick visual comparison of values without a chart. Arrows belong to Icon Sets." },
    fr: { q: "Qu'affichent les barres de données en mise en forme conditionnelle ?", o: ["Une barre colorée dans chaque cellule, de longueur proportionnelle à sa valeur", "Un graphique séparé sur une nouvelle feuille", "Seulement une flèche vers le haut ou le bas", "Des bordures autour des cellules"], e: "Les barres de données offrent une comparaison visuelle rapide sans graphique. Les flèches font partie des jeux d'icônes." } },
  { level: 4,
    ar: { q: "كيف تُبرز القيم المكررة في عمود بسرعة؟", o: ["تنسيق شرطي ← قواعد تمييز الخلايا ← القيم المكررة", "بيانات ← إزالة التكرارات", "فرز من A إلى Z", "Ctrl+D"], e: "«القيم المكررة» تلوّن التكرارات دون حذف أي شيء. أما «إزالة التكرارات» فتحذفها فعليًا، فاحذر الخلط بينهما." },
    en: { q: "How do you quickly highlight duplicate values in a column?", o: ["Conditional Formatting → Highlight Cells Rules → Duplicate Values", "Data → Remove Duplicates", "Sort A to Z", "Ctrl+D"], e: "Duplicate Values colours repeats without deleting anything. Remove Duplicates actually deletes them — do not confuse the two." },
    fr: { q: "Comment mettre rapidement en évidence les doublons d'une colonne ?", o: ["Mise en forme conditionnelle → Règles de mise en surbrillance → Valeurs en double", "Données → Supprimer les doublons", "Trier de A à Z", "Ctrl+D"], e: "« Valeurs en double » colore les répétitions sans rien supprimer. « Supprimer les doublons », lui, les efface réellement — ne pas confondre." } },
  { level: 4,
    ar: { q: "ما أنسب نوع مخطط لعرض تطور المبيعات الشهرية خلال سنة؟", o: ["مخطط خطي (Line)", "مخطط دائري (Pie)", "مخطط مبعثر بدون خطوط", "مخطط رادار"], e: "المخطط الخطي يُبرز الاتجاه عبر الزمن (صعود، هبوط، موسمية)، والمحور الأفقي فيه يمثل التسلسل الزمني." },
    en: { q: "Which chart type best shows monthly sales over a year?", o: ["Line chart", "Pie chart", "Scatter without lines", "Radar chart"], e: "A line chart highlights the trend over time (rises, falls, seasonality), with the horizontal axis as the time sequence." },
    fr: { q: "Quel type de graphique montre le mieux l'évolution des ventes mensuelles sur un an ?", o: ["Courbe (graphique en lignes)", "Secteurs (camembert)", "Nuage de points sans lignes", "Radar"], e: "La courbe met en évidence la tendance dans le temps (hausses, baisses, saisonnalité), l'axe horizontal représentant la chronologie." } },
  { level: 4,
    ar: { q: "متى يكون المخطط الدائري (Pie) مناسبًا؟", o: ["لعرض أجزاء من كل واحد في سلسلة واحدة وعدد قليل من الفئات", "لعرض تطور قيمة عبر 24 شهرًا", "لمقارنة عدة سلاسل معًا", "لعرض العلاقة بين متغيرين رقميين"], e: "الدائري يوضح النسب من المجموع (مثل حصة كل قسم من الميزانية). مع فئات كثيرة أو عدة سلاسل يصبح مخطط الأعمدة أوضح." },
    en: { q: "When is a pie chart appropriate?", o: ["To show parts of a whole for a single series with few categories", "To show a value over 24 months", "To compare several series", "To show the relationship between two numeric variables"], e: "A pie shows shares of a total (e.g. each department's share of the budget). With many categories or several series, a column chart is clearer." },
    fr: { q: "Quand un graphique en secteurs est-il approprié ?", o: ["Pour montrer les parts d'un tout, sur une seule série avec peu de catégories", "Pour montrer une valeur sur 24 mois", "Pour comparer plusieurs séries", "Pour montrer la relation entre deux variables numériques"], e: "Le secteur montre des parts d'un total (ex. part de chaque service dans le budget). Avec beaucoup de catégories ou plusieurs séries, un histogramme est plus lisible." } },
  { level: 4,
    ar: { q: "أي مخطط يُستخدم لدراسة العلاقة بين متغيرين رقميين، مثل درجة الحرارة واستهلاك الطاقة؟", o: ["مخطط مبعثر (XY Scatter)", "مخطط دائري", "مخطط أعمدة مكدسة", "مخطط مساحي"], e: "المبعثر يضع كل زوج من القيم كنقطة (X، Y)، ويمكن إضافة «خط اتجاه» ومعادلته وقيمة R² لقياس قوة الارتباط." },
    en: { q: "Which chart is used to study the relationship between two numeric variables, such as temperature and energy use?", o: ["XY Scatter chart", "Pie chart", "Stacked column chart", "Area chart"], e: "A scatter plots each pair of values as a point (X, Y); you can add a trendline with its equation and R² to measure the strength of the correlation." },
    fr: { q: "Quel graphique sert à étudier la relation entre deux variables numériques, comme la température et la consommation d'énergie ?", o: ["Nuage de points (XY)", "Secteurs", "Histogramme empilé", "Aires"], e: "Le nuage place chaque couple de valeurs en point (X, Y) ; on peut ajouter une courbe de tendance avec son équation et R² pour mesurer la corrélation." } },
  { level: 4,
    ar: { q: "ماذا يحدث عند تحديد بيانات والضغط على F11؟", o: ["يُنشأ مخطط افتراضي في ورقة مخطط مستقلة", "يُنشأ جدول محوري", "يُفتح محرر VBA", "تُحفظ نسخة من الملف"], e: "F11 يُنشئ مخططًا في ورقة خاصة (Chart Sheet)، أما Alt+F1 فيُنشئه مضمّنًا داخل الورقة الحالية." },
    en: { q: "What happens when you select data and press F11?", o: ["A default chart is created on a separate chart sheet", "A PivotTable is created", "The VBA editor opens", "A copy of the file is saved"], e: "F11 creates a chart on its own chart sheet; Alt+F1 creates it embedded in the current sheet." },
    fr: { q: "Que se passe-t-il quand on sélectionne des données et qu'on appuie sur F11 ?", o: ["Un graphique par défaut est créé sur une feuille graphique séparée", "Un tableau croisé dynamique est créé", "L'éditeur VBA s'ouvre", "Une copie du fichier est enregistrée"], e: "F11 crée un graphique sur sa propre feuille graphique ; Alt+F1 le crée incorporé dans la feuille actuelle." } },
  { level: 4,
    ar: { q: "متى نستخدم «محورًا ثانويًا» في مخطط مركّب (Combo)؟", o: ["عندما تختلف مقاييس السلسلتين كثيرًا، مثل المبيعات بالملايين ونسبة الربح بالمئة", "عندما تكون السلسلتان متطابقتين", "لإخفاء سلسلة", "لتحويل المخطط إلى دائري"], e: "المحور الثانوي يعطي السلسلة الثانية مقياسًا خاصًا على الجانب الآخر، فلا تبدو مسطحة بجانب السلسلة ذات القيم الكبيرة." },
    en: { q: "When do we use a secondary axis in a combo chart?", o: ["When the two series have very different scales, e.g. sales in millions and profit margin in %", "When both series are identical", "To hide a series", "To turn the chart into a pie"], e: "A secondary axis gives the second series its own scale on the other side, so it does not look flat next to the large-valued series." },
    fr: { q: "Quand utilise-t-on un axe secondaire dans un graphique combiné ?", o: ["Quand les deux séries ont des échelles très différentes, ex. ventes en millions et marge en %", "Quand les deux séries sont identiques", "Pour masquer une série", "Pour transformer le graphique en secteurs"], e: "L'axe secondaire donne à la 2e série sa propre échelle de l'autre côté, pour qu'elle ne paraisse pas plate à côté de la série aux grandes valeurs." } },
  { level: 4,
    ar: { q: "ما «خطوط المؤشرات» (Sparklines)؟", o: ["مخططات صغيرة داخل خلية واحدة تُظهر اتجاه صف من البيانات", "خطوط الشبكة الرمادية", "حدود الخلايا المنقطة", "أسهم تتبّع المعادلات"], e: "من تبويب «إدراج» ← خطوط المؤشرات (خط، عمود، ربح/خسارة)، وهي ممتازة في لوحات المتابعة لعرض الاتجاه بجانب الأرقام." },
    en: { q: "What are Sparklines?", o: ["Tiny charts inside a single cell showing the trend of a row of data", "The grey gridlines", "Dotted cell borders", "Formula-tracing arrows"], e: "Insert → Sparklines (Line, Column, Win/Loss). Great in dashboards for showing a trend next to the numbers." },
    fr: { q: "Que sont les graphiques sparkline ?", o: ["De mini-graphiques dans une seule cellule montrant la tendance d'une ligne de données", "Le quadrillage gris", "Des bordures en pointillés", "Des flèches d'audit de formules"], e: "Insertion → Graphiques sparkline (Courbe, Histogramme, Positif/Négatif). Parfaits dans les tableaux de bord pour montrer la tendance à côté des chiffres." } },
  { level: 4,
    ar: { q: "كيف تُنشئ قائمة منسدلة داخل خلية؟", o: ["بيانات ← التحقق من صحة البيانات ← السماح: قائمة ← تحديد المصدر", "إدراج ← قائمة", "الصفحة الرئيسية ← تعبئة", "صيغ ← تعريف اسم فقط"], e: "اختر «قائمة» في التحقق من صحة البيانات واكتب العناصر مفصولة بفواصل أو حدد نطاقًا يحتويها. يُفضَّل أن يكون المصدر جدولًا أو نطاقًا مسمّى ليتحدث تلقائيًا." },
    en: { q: "How do you create a drop-down list in a cell?", o: ["Data → Data Validation → Allow: List → set the Source", "Insert → List", "Home → Fill", "Formulas → Define Name only"], e: "Choose List in Data Validation and type the items separated by commas or point to a range holding them. A Table or named range as source keeps the list up to date." },
    fr: { q: "Comment créer une liste déroulante dans une cellule ?", o: ["Données → Validation des données → Autoriser : Liste → définir la Source", "Insertion → Liste", "Accueil → Remplissage", "Formules → Définir un nom uniquement"], e: "Choisissez Liste dans la Validation des données et tapez les éléments séparés par des points-virgules ou désignez une plage. Un tableau ou une plage nommée comme source garde la liste à jour." } },
  { level: 4,
    ar: { q: "هل يمكن لعملية «نسخ ولصق» أن تتجاوز قاعدة التحقق من صحة البيانات؟", o: ["نعم، اللصق العادي يستبدل محتوى الخلية وقاعدتها دون أي تحذير", "لا، القاعدة تمنع أي لصق", "فقط إذا كانت الورقة محمية", "فقط مع النصوص"], e: "التحقق يعمل عند الكتابة اليدوية فقط. لاكتشاف القيم المخالفة الموجودة استخدم: التحقق من صحة البيانات ← وضع دائرة حول البيانات غير الصالحة." },
    en: { q: "Can copy-and-paste bypass a Data Validation rule?", o: ["Yes — a normal paste replaces the cell's content and its rule without warning", "No, the rule blocks any paste", "Only if the sheet is protected", "Only with text"], e: "Validation only checks manual typing. To find invalid values already present use Data Validation → Circle Invalid Data." },
    fr: { q: "Un copier-coller peut-il contourner une règle de validation des données ?", o: ["Oui — un collage normal remplace le contenu et la règle de la cellule sans avertissement", "Non, la règle bloque tout collage", "Seulement si la feuille est protégée", "Seulement avec du texte"], e: "La validation ne contrôle que la saisie manuelle. Pour repérer les valeurs non conformes existantes : Validation des données → Entourer les données non valides." } },
  { level: 4,
    ar: { q: "في نافذة التحقق من صحة البيانات، أي نمط من «تنبيه الخطأ» يمنع إدخال القيمة غير الصالحة نهائيًا؟", o: ["إيقاف (Stop)", "تحذير (Warning)", "معلومات (Information)", "رسالة الإدخال"], e: "«إيقاف» يرفض القيمة. «تحذير» و«معلومات» يسمحان بإدخالها بعد التنبيه. أما «رسالة الإدخال» فهي تلميح يظهر عند تحديد الخلية فقط." },
    en: { q: "In Data Validation, which Error Alert style completely blocks an invalid entry?", o: ["Stop", "Warning", "Information", "Input Message"], e: "Stop rejects the value. Warning and Information let it through after the alert. The Input Message is only a tip shown when the cell is selected." },
    fr: { q: "Dans la validation des données, quel style d'alerte d'erreur bloque totalement une saisie non valide ?", o: ["Arrêt", "Avertissement", "Informations", "Message de saisie"], e: "Arrêt refuse la valeur. Avertissement et Informations la laissent passer après l'alerte. Le Message de saisie n'est qu'une aide affichée à la sélection de la cellule." } },
  /* ===================== LEVEL 5 — PivotTables, nested functions, protection, pro shortcuts, macros ===================== */
  { level: 5,
    ar: { q: "ما الغرض الأساسي من «الجدول المحوري» (PivotTable)؟", o: ["تلخيص وتحليل كمّ كبير من البيانات بسحب الحقول إلى الصفوف والأعمدة والقيم والمرشحات", "رسم الأشكال الهندسية", "حماية البيانات بكلمة سر", "تصحيح الأخطاء الإملائية"], e: "الجدول المحوري يجمع ويعدّ ويحسب المتوسطات حسب الفئات في ثوانٍ ودون أي معادلة، ويمكن إعادة ترتيبه بالسحب والإفلات." },
    en: { q: "What is the main purpose of a PivotTable?", o: ["Summarising and analysing large data by dragging fields into Rows, Columns, Values and Filters", "Drawing shapes", "Protecting data with a password", "Fixing spelling mistakes"], e: "A PivotTable sums, counts and averages by category in seconds without any formula, and can be rearranged by drag and drop." },
    fr: { q: "Quel est le but principal d'un tableau croisé dynamique ?", o: ["Synthétiser et analyser de grandes données en glissant des champs dans Lignes, Colonnes, Valeurs et Filtres", "Dessiner des formes", "Protéger les données par mot de passe", "Corriger l'orthographe"], e: "Le TCD additionne, compte et fait des moyennes par catégorie en quelques secondes sans formule, et se réorganise par glisser-déposer." } },
  { level: 5,
    ar: { q: "عند سحب حقل نصي (مثل «اسم الموظف») إلى منطقة «القيم» في الجدول المحوري، ما العملية الافتراضية؟", o: ["العدد (Count)", "المجموع (Sum)", "المتوسط (Average)", "الحد الأقصى (Max)"], e: "النصوص لا تُجمع، فيستخدم إكسل «العدد». الحقول الرقمية تُجمع افتراضيًا (إلا إذا احتوت خلايا فارغة أو نصوصًا فتتحول إلى عدد)." },
    en: { q: "When you drag a text field (e.g. “Employee name”) into the PivotTable Values area, what is the default summary?", o: ["Count", "Sum", "Average", "Max"], e: "Text cannot be summed, so Excel uses Count. Numeric fields are summed by default (unless they contain blanks or text, in which case Count is used)." },
    fr: { q: "Quand on glisse un champ texte (ex. « Nom de l'employé ») dans la zone Valeurs d'un TCD, quelle synthèse est appliquée par défaut ?", o: ["Nombre", "Somme", "Moyenne", "Max"], e: "Le texte ne s'additionne pas : Excel utilise Nombre. Les champs numériques sont additionnés par défaut (sauf s'ils contiennent des vides ou du texte, auquel cas Nombre est utilisé)." } },
  { level: 5,
    ar: { q: "عدّلت أرقامًا في بيانات المصدر، لكن الجدول المحوري لم يتغير. ما الحل؟", o: ["تحديث الجدول المحوري (زر الفأرة الأيمن ← تحديث، أو Alt+F5)", "حذف الجدول وإعادة إنشائه دائمًا", "حفظ الملف بصيغة CSV", "تغيير لون الخلايا"], e: "الجدول المحوري يعمل على نسخة مخزنة (Cache) من البيانات ولا يتحدث تلقائيًا. Alt+F5 يحدّث الجدول الحالي وCtrl+Alt+F5 يحدّث الكل." },
    en: { q: "You changed numbers in the source data, but the PivotTable did not change. What is the fix?", o: ["Refresh the PivotTable (right-click → Refresh, or Alt+F5)", "Always delete and rebuild it", "Save the file as CSV", "Change the cell colours"], e: "A PivotTable works on a stored cache of the data and does not update by itself. Alt+F5 refreshes the current one; Ctrl+Alt+F5 refreshes all." },
    fr: { q: "Vous avez modifié des chiffres dans les données source, mais le TCD n'a pas changé. Que faire ?", o: ["Actualiser le TCD (clic droit → Actualiser, ou Alt+F5)", "Toujours le supprimer et le recréer", "Enregistrer le fichier en CSV", "Changer la couleur des cellules"], e: "Le TCD travaille sur un cache des données et ne se met pas à jour seul. Alt+F5 actualise le TCD courant ; Ctrl+Alt+F5 actualise tout." } },
  { level: 5,
    ar: { q: "كيف تعرض في الجدول المحوري حصة كل منطقة كنسبة مئوية من الإجمالي العام؟", o: ["إعدادات حقل القيمة ← إظهار القيم كـ ← % من الإجمالي الكلي", "تغيير تنسيق الأرقام إلى نسبة مئوية فقط", "إضافة عمود يدوي خارج الجدول", "ذلك غير ممكن"], e: "«إظهار القيم كـ» يعيد حساب الأرقام كنسب من الإجمالي أو من الصف أو العمود، أو كفرق عن عنصر آخر… أما تغيير التنسيق وحده فيضرب الأرقام في 100 فقط ويعطي نتائج خاطئة." },
    en: { q: "In a PivotTable, how do you show each region's share as a percentage of the grand total?", o: ["Value Field Settings → Show Values As → % of Grand Total", "Just change the number format to Percentage", "Add a manual column outside the table", "It is not possible"], e: "Show Values As recalculates numbers as % of total, row or column, difference from another item… Changing the format alone just multiplies the numbers by 100 and gives wrong results." },
    fr: { q: "Dans un TCD, comment afficher la part de chaque région en pourcentage du total général ?", o: ["Paramètres des champs de valeurs → Afficher les valeurs → % du total général", "Changer seulement le format en Pourcentage", "Ajouter une colonne manuelle hors du tableau", "Ce n'est pas possible"], e: "« Afficher les valeurs » recalcule en % du total, de la ligne ou de la colonne, en différence par rapport à un élément… Changer seulement le format multiplie les nombres par 100 et donne des résultats faux." } },
  { level: 5,
    ar: { q: "ما «مقسّم طرق العرض» (Slicer)؟", o: ["أزرار مرئية لتصفية الجدول المحوري (أو الجدول) بنقرة، وتُظهر عامل التصفية الحالي بوضوح", "أداة لتقسيم الخلية إلى خليتين", "أداة لقص الصور", "خط فاصل بين الأوراق"], e: "المقسّمات تجعل التصفية سهلة لأي مستخدم، ويمكن ربط مقسّم واحد بعدة جداول محورية في الوقت نفسه. وللتواريخ يوجد «المخطط الزمني» (Timeline)." },
    en: { q: "What is a Slicer?", o: ["Visual buttons that filter a PivotTable (or table) in one click and clearly show the current filter", "A tool that splits a cell in two", "An image-cropping tool", "A divider between sheets"], e: "Slicers make filtering easy for anyone, and one slicer can be connected to several PivotTables at once. For dates there is the Timeline." },
    fr: { q: "Qu'est-ce qu'un segment (Slicer) ?", o: ["Des boutons visuels qui filtrent un TCD (ou un tableau) en un clic et montrent clairement le filtre actif", "Un outil qui divise une cellule en deux", "Un outil de rognage d'images", "Un séparateur entre feuilles"], e: "Les segments rendent le filtrage facile pour tous, et un segment peut piloter plusieurs TCD à la fois. Pour les dates, il existe la chronologie (Timeline)." } },
  { level: 5,
    ar: { q: "حقل تاريخ يومي في صفوف الجدول المحوري. كيف تلخّصه حسب الأشهر والسنوات؟", o: ["زر الفأرة الأيمن على أحد التواريخ ← تجميع ← اختيار الأشهر والسنوات", "إضافة عمود يدوي لكل شهر", "تحويل التواريخ إلى نص", "فرز التواريخ فقط"], e: "«التجميع» يجمع التواريخ حسب الأيام أو الأشهر أو الأرباع أو السنوات، ويجمع الأرقام في فئات (مثل الأعمار 20-29، 30-39…)." },
    en: { q: "A daily date field is in the PivotTable rows. How do you summarise it by months and years?", o: ["Right-click a date → Group → choose Months and Years", "Add a manual column for each month", "Convert the dates to text", "Just sort the dates"], e: "Grouping rolls dates up by days, months, quarters or years, and groups numbers into bins (e.g. ages 20-29, 30-39…)." },
    fr: { q: "Un champ de dates journalières est en lignes du TCD. Comment le synthétiser par mois et par année ?", o: ["Clic droit sur une date → Grouper → choisir Mois et Années", "Ajouter une colonne manuelle par mois", "Convertir les dates en texte", "Trier simplement les dates"], e: "Grouper regroupe les dates par jours, mois, trimestres ou années, et les nombres par tranches (ex. âges 20-29, 30-39…)." } },
  { level: 5,
    ar: { q: "لماذا يُنصح بتحويل بيانات المصدر إلى «جدول» (Ctrl+T) قبل إنشاء الجدول المحوري؟", o: ["لأن نطاق المصدر يتوسع تلقائيًا مع الصفوف الجديدة، فتكفي عملية التحديث", "لأن الجدول المحوري لا يعمل بدونه", "لتصغير حجم الملف إلى النصف", "لحماية البيانات من التعديل"], e: "مع النطاق العادي قد تُستبعد الصفوف المضافة أسفل البيانات. الجدول المنسق يتمدد تلقائيًا، فيشملها الجدول المحوري بعد التحديث." },
    en: { q: "Why is it recommended to turn the source data into a Table (Ctrl+T) before creating a PivotTable?", o: ["The source range then grows automatically with new rows, so a Refresh is enough", "PivotTables do not work without it", "It halves the file size", "It protects the data from editing"], e: "With a plain range, rows added below the data may be left out. A formatted Table expands automatically, so the PivotTable includes them after a refresh." },
    fr: { q: "Pourquoi conseille-t-on de convertir les données source en Tableau (Ctrl+T) avant de créer un TCD ?", o: ["La plage source s'étend alors automatiquement avec les nouvelles lignes ; il suffit d'actualiser", "Le TCD ne fonctionne pas sans", "Cela divise la taille du fichier par deux", "Cela protège les données contre la modification"], e: "Avec une plage normale, les lignes ajoutées en dessous peuvent être oubliées. Un tableau mis en forme s'étend automatiquement : le TCD les inclut après actualisation." } },
  { level: 5,
    ar: { q: "ما «الحقل المحسوب» (Calculated Field) في الجدول المحوري؟", o: ["حقل جديد تُنشئه بمعادلة تعتمد على حقول أخرى، مثل الربح = المبيعات - التكلفة", "حقل يُحذف تلقائيًا", "عمود يُضاف إلى بيانات المصدر", "خلية تحتوي تاريخ التحديث"], e: "من تحليل الجدول المحوري ← الحقول والعناصر والمجموعات ← حقل محسوب. يُحسب داخل الجدول المحوري دون تعديل بيانات المصدر." },
    en: { q: "What is a Calculated Field in a PivotTable?", o: ["A new field you create with a formula based on other fields, e.g. Profit = Sales - Cost", "A field that is deleted automatically", "A column added to the source data", "A cell holding the refresh date"], e: "PivotTable Analyze → Fields, Items & Sets → Calculated Field. It is computed inside the PivotTable without changing the source data." },
    fr: { q: "Qu'est-ce qu'un champ calculé dans un TCD ?", o: ["Un nouveau champ créé par une formule à partir d'autres champs, ex. Marge = Ventes - Coût", "Un champ supprimé automatiquement", "Une colonne ajoutée aux données source", "Une cellule contenant la date d'actualisation"], e: "Analyse du TCD → Calculs → Champs, éléments et jeux → Champ calculé. Il est calculé dans le TCD sans modifier les données source." } },
  { level: 5,
    ar: { q: "A1 = 12. ما نتيجة {{=IF(A1>=16,\"Excellent\",IF(A1>=10,\"Pass\",\"Fail\"))}}؟", o: ["Pass", "Excellent", "Fail", "FALSE"], e: "الشرط الأول (12>=16) خاطئ، فننتقل إلى IF الداخلية: 12>=10 صحيح ← «Pass»." },
    en: { q: "A1 = 12. What does {{=IF(A1>=16,\"Excellent\",IF(A1>=10,\"Pass\",\"Fail\"))}} return?", o: ["Pass", "Excellent", "Fail", "FALSE"], e: "The first test (12>=16) is false, so the inner IF runs: 12>=10 is true → “Pass”." },
    fr: { q: "A1 = 12. Que renvoie {{=IF(A1>=16,\"Excellent\",IF(A1>=10,\"Pass\",\"Fail\"))}} ?", o: ["Pass", "Excellent", "Fail", "FALSE"], e: "Le 1er test (12>=16) est faux, donc le IF imbriqué s'exécute : 12>=10 est vrai → « Pass »." } },
  { level: 5,
    ar: { q: "A1 = 18. ما نتيجة {{=IF(A1>=10,\"Pass\",IF(A1>=16,\"Excellent\",\"Fail\"))}}؟", o: ["Pass", "Excellent", "Fail", "خطأ"], e: "الشرط الأول 18>=10 صحيح فتتوقف IF فورًا وتُرجع «Pass»، ولن يُفحص شرط Excellent أبدًا. في IF المتداخلة ابدأ دائمًا بالشرط الأكثر تقييدًا." },
    en: { q: "A1 = 18. What does {{=IF(A1>=10,\"Pass\",IF(A1>=16,\"Excellent\",\"Fail\"))}} return?", o: ["Pass", "Excellent", "Fail", "An error"], e: "The first test 18>=10 is true, so IF stops at once and returns “Pass”; the Excellent test is never reached. In nested IFs always start with the most restrictive condition." },
    fr: { q: "A1 = 18. Que renvoie {{=IF(A1>=10,\"Pass\",IF(A1>=16,\"Excellent\",\"Fail\"))}} ?", o: ["Pass", "Excellent", "Fail", "Une erreur"], e: "Le 1er test 18>=10 est vrai : IF s'arrête aussitôt et renvoie « Pass » ; le test Excellent n'est jamais atteint. Dans des IF imbriqués, commencez toujours par la condition la plus restrictive." } },
  { level: 5,
    ar: { q: "ما ميزة الدالة IFS مقارنةً بـ IF المتداخلة؟", o: ["تختبر عدة شروط بالترتيب في دالة واحدة دون تداخل الأقواس", "تعمل في كل الإصدارات القديمة", "تُرجع عدة نتائج في نفس الخلية", "تتجاهل ترتيب الشروط"], e: "مثال: {{=IFS(A1>=16,\"Excellent\",A1>=10,\"Pass\",TRUE,\"Fail\")}}. الشرط TRUE الأخير يمثل «غير ذلك». متوفرة منذ إكسل 2019 و365." },
    en: { q: "What is the advantage of IFS over nested IFs?", o: ["It tests several conditions in order in one function, without nested brackets", "It works in all old versions", "It returns several results in one cell", "It ignores the order of conditions"], e: "Example: {{=IFS(A1>=16,\"Excellent\",A1>=10,\"Pass\",TRUE,\"Fail\")}}. The final TRUE acts as “otherwise”. Available since Excel 2019 and 365." },
    fr: { q: "Quel est l'avantage de IFS (SI.CONDITIONS) sur des IF imbriqués ?", o: ["Elle teste plusieurs conditions dans l'ordre en une seule fonction, sans parenthèses imbriquées", "Elle fonctionne dans toutes les anciennes versions", "Elle renvoie plusieurs résultats dans une cellule", "Elle ignore l'ordre des conditions"], e: "Exemple : {{=IFS(A1>=16,\"Excellent\",A1>=10,\"Pass\",TRUE,\"Fail\")}}. Le TRUE final joue le rôle de « sinon ». Disponible depuis Excel 2019 et 365." } },
  { level: 5,
    ar: { q: "B1 = 0. ما نتيجة {{=IFERROR(A1/B1,0)}}؟", o: ["0", "#DIV/0!", "A1", "خلية فارغة"], e: "القسمة على صفر تعطي #DIV/0!، فتلتقطها IFERROR وتُرجع البديل 0. انتبه: IFERROR تُخفي كل أنواع الأخطاء، حتى الأخطاء التي يجب أن تراها." },
    en: { q: "B1 = 0. What does {{=IFERROR(A1/B1,0)}} return?", o: ["0", "#DIV/0!", "A1", "An empty cell"], e: "Dividing by zero gives #DIV/0!, which IFERROR catches and replaces with 0. Careful: IFERROR hides every error type, even ones you should see." },
    fr: { q: "B1 = 0. Que renvoie {{=IFERROR(A1/B1,0)}} ?", o: ["0", "#DIV/0!", "A1", "Une cellule vide"], e: "Diviser par zéro donne #DIV/0!, intercepté par IFERROR (SIERREUR) qui renvoie 0. Attention : IFERROR masque tous les types d'erreurs, même celles qu'il faudrait voir." } },
  { level: 5,
    ar: { q: "A1:A3 تحتوي 10، 11، 13. ما نتيجة {{=ROUND(AVERAGE(A1:A3),1)}}؟", o: ["11.3", "11.33", "11", "34"], e: "تُحسب الدالة الداخلية أولًا: المتوسط = 34 ÷ 3 = 11.333…، ثم تقرّبه ROUND إلى منزلة عشرية واحدة: 11.3." },
    en: { q: "A1:A3 contains 10, 11, 13. What does {{=ROUND(AVERAGE(A1:A3),1)}} return?", o: ["11.3", "11.33", "11", "34"], e: "The inner function runs first: average = 34 ÷ 3 = 11.333…, then ROUND keeps one decimal: 11.3." },
    fr: { q: "A1:A3 contient 10, 11, 13. Que renvoie {{=ROUND(AVERAGE(A1:A3),1)}} ?", o: ["11,3", "11,33", "11", "34"], e: "La fonction intérieure s'exécute d'abord : moyenne = 34 ÷ 3 = 11,333…, puis ROUND garde une décimale : 11,3." } },
  { level: 5,
    ar: { q: "ماذا تحسب {{=SUMIFS(C:C,A:A,\"North\",B:B,\">1000\")}}؟", o: ["مجموع C للصفوف التي يكون فيها A = North و B أكبر من 1000 معًا", "مجموع C للصفوف التي تحقق أحد الشرطين فقط", "عدد الصفوف التي تحقق الشرطين", "مجموع A وB"], e: "SUMIFS تربط الشروط بـ «و» (AND): يجب تحقق كل الشروط في الصف نفسه حتى تُجمع قيمته." },
    en: { q: "What does {{=SUMIFS(C:C,A:A,\"North\",B:B,\">1000\")}} calculate?", o: ["The sum of C for rows where A = North AND B is greater than 1000", "The sum of C for rows meeting either condition", "The number of rows meeting both conditions", "The sum of A and B"], e: "SUMIFS joins its conditions with AND: every condition must be true on the same row for its value to be added." },
    fr: { q: "Que calcule {{=SUMIFS(C:C,A:A,\"North\",B:B,\">1000\")}} ?", o: ["La somme de C pour les lignes où A = North ET B est supérieur à 1000", "La somme de C pour les lignes remplissant l'une ou l'autre condition", "Le nombre de lignes remplissant les deux conditions", "La somme de A et B"], e: "SUMIFS (SOMME.SI.ENS) relie ses conditions par ET : toutes doivent être vraies sur la même ligne pour que la valeur soit additionnée." } },
  { level: 5,
    ar: { q: "الأسماء في B2:B10 والمبيعات في C2:C10. ماذا تُرجع {{=INDEX(B2:B10,MATCH(MAX(C2:C10),C2:C10,0))}}؟", o: ["اسم الشخص صاحب أعلى مبيعات", "أعلى قيمة مبيعات", "موضع أعلى قيمة", "مجموع المبيعات"], e: "MAX تجد أعلى رقم، وMATCH تحدد موضعه، وINDEX تُرجع الاسم الموجود في الموضع نفسه. مثال كلاسيكي على تداخل ثلاث دوال." },
    en: { q: "Names are in B2:B10 and sales in C2:C10. What does {{=INDEX(B2:B10,MATCH(MAX(C2:C10),C2:C10,0))}} return?", o: ["The name of the person with the highest sales", "The highest sales value", "The position of the highest value", "Total sales"], e: "MAX finds the top number, MATCH finds its position, and INDEX returns the name at that same position — a classic three-function nest." },
    fr: { q: "Les noms sont en B2:B10 et les ventes en C2:C10. Que renvoie {{=INDEX(B2:B10,MATCH(MAX(C2:C10),C2:C10,0))}} ?", o: ["Le nom de la personne ayant les meilleures ventes", "La plus forte valeur de ventes", "La position de la plus forte valeur", "Le total des ventes"], e: "MAX trouve le plus grand nombre, MATCH sa position, et INDEX renvoie le nom à la même position — un imbriquement classique de trois fonctions." } },
  { level: 5,
    ar: { q: "ما نتيجة {{=UPPER(LEFT(\"merabti\",3))}}؟", o: ["MER", "mer", "TIB", "MERABTI"], e: "LEFT تأخذ أول 3 أحرف «mer»، ثم UPPER تحوّلها إلى أحرف كبيرة: «MER»." },
    en: { q: "What does {{=UPPER(LEFT(\"merabti\",3))}} return?", o: ["MER", "mer", "TIB", "MERABTI"], e: "LEFT takes the first 3 characters “mer”, then UPPER converts them to capitals: “MER”." },
    fr: { q: "Que renvoie {{=UPPER(LEFT(\"merabti\",3))}} ?", o: ["MER", "mer", "TIB", "MERABTI"], e: "LEFT (GAUCHE) prend les 3 premiers caractères « mer », puis UPPER (MAJUSCULE) les met en capitales : « MER »." } },
  { level: 5,
    ar: { q: "تريد أن يعدّل المستخدمون خلايا الإدخال فقط في ورقة محمية. ما الطريقة الصحيحة؟", o: ["إلغاء خيار «مؤمّنة» لخلايا الإدخال من تنسيق الخلايا ← حماية، ثم تفعيل «حماية الورقة»", "حماية الورقة فقط", "إخفاء بقية الخلايا", "تلوين خلايا الإدخال بالأصفر"], e: "كل الخلايا «مؤمّنة» افتراضيًا، لكن هذا لا يعمل إلا بعد حماية الورقة. لذلك نلغي التأمين عن خلايا الإدخال أولًا ثم نحمي الورقة." },
    en: { q: "You want users to edit only the input cells of a protected sheet. What is the correct method?", o: ["Untick “Locked” for the input cells in Format Cells → Protection, then turn on Protect Sheet", "Just protect the sheet", "Hide the other cells", "Colour the input cells yellow"], e: "All cells are Locked by default, but this only takes effect once the sheet is protected. So unlock the input cells first, then protect the sheet." },
    fr: { q: "Vous voulez que les utilisateurs ne modifient que les cellules de saisie d'une feuille protégée. Quelle est la bonne méthode ?", o: ["Décocher « Verrouillée » pour les cellules de saisie dans Format de cellule → Protection, puis activer Protéger la feuille", "Protéger seulement la feuille", "Masquer les autres cellules", "Colorer les cellules de saisie en jaune"], e: "Toutes les cellules sont verrouillées par défaut, mais cela n'agit qu'une fois la feuille protégée. On déverrouille donc d'abord les cellules de saisie, puis on protège la feuille." } },
  { level: 5,
    ar: { q: "ماذا تمنع «حماية بنية المصنف» (Protect Workbook)؟", o: ["إضافة الأوراق أو حذفها أو إعادة تسميتها أو نقلها أو إظهار المخفي منها", "تعديل محتوى الخلايا", "فتح الملف", "الطباعة"], e: "حماية المصنف تحمي «البنية» (الأوراق)، أما حماية الورقة فتحمي الخلايا، والتشفير بكلمة مرور يمنع فتح الملف." },
    en: { q: "What does Protect Workbook (structure) prevent?", o: ["Adding, deleting, renaming, moving or unhiding sheets", "Editing cell contents", "Opening the file", "Printing"], e: "Protect Workbook guards the structure (sheets); Protect Sheet guards the cells; encrypting with a password prevents the file from being opened." },
    fr: { q: "Qu'empêche « Protéger le classeur » (structure) ?", o: ["Ajouter, supprimer, renommer, déplacer ou afficher des feuilles masquées", "Modifier le contenu des cellules", "Ouvrir le fichier", "Imprimer"], e: "Protéger le classeur protège la structure (les feuilles) ; Protéger la feuille protège les cellules ; le chiffrement par mot de passe empêche d'ouvrir le fichier." } },
  { level: 5,
    ar: { q: "كيف تمنع أي شخص لا يعرف كلمة المرور من فتح الملف أصلًا؟", o: ["ملف ← معلومات ← حماية المصنف ← تشفير باستخدام كلمة مرور", "حماية الورقة", "حماية بنية المصنف", "إخفاء كل الأوراق"], e: "التشفير هو الحماية الحقيقية للمحتوى. حماية الورقة والمصنف تمنع التعديل غير المقصود لكنها ليست وسيلة أمان قوية. ولا يمكن استرجاع كلمة مرور التشفير إذا نُسيت." },
    en: { q: "How do you stop anyone without the password from opening the file at all?", o: ["File → Info → Protect Workbook → Encrypt with Password", "Protect Sheet", "Protect Workbook structure", "Hide all sheets"], e: "Encryption is the real protection for the content. Sheet and workbook protection prevent accidental changes but are not strong security. An encryption password cannot be recovered if forgotten." },
    fr: { q: "Comment empêcher toute personne sans mot de passe d'ouvrir le fichier ?", o: ["Fichier → Informations → Protéger le classeur → Chiffrer avec mot de passe", "Protéger la feuille", "Protéger la structure du classeur", "Masquer toutes les feuilles"], e: "Le chiffrement est la vraie protection du contenu. Les protections de feuille et de classeur évitent les modifications accidentelles mais ne sont pas une sécurité forte. Un mot de passe de chiffrement oublié est irrécupérable." } },
  { level: 5,
    ar: { q: "كيف تُخفي معادلة من شريط الصيغة مع بقاء نتيجتها ظاهرة في الخلية؟", o: ["تفعيل خيار «مخفية» من تنسيق الخلايا ← حماية، ثم حماية الورقة", "تلوين الخط بالأبيض", "إخفاء العمود", "تحويل المعادلة إلى قيمة"], e: "خيار «مخفية» لا يعمل إلا بعد حماية الورقة. تلوين الخط بالأبيض لا يُخفي المعادلة من شريط الصيغة." },
    en: { q: "How do you hide a formula from the formula bar while keeping its result visible in the cell?", o: ["Tick “Hidden” in Format Cells → Protection, then protect the sheet", "Colour the font white", "Hide the column", "Convert the formula to a value"], e: "“Hidden” only takes effect once the sheet is protected. A white font does not hide the formula from the formula bar." },
    fr: { q: "Comment masquer une formule dans la barre de formule tout en gardant son résultat visible ?", o: ["Cocher « Masquée » dans Format de cellule → Protection, puis protéger la feuille", "Mettre la police en blanc", "Masquer la colonne", "Convertir la formule en valeur"], e: "« Masquée » n'agit qu'une fois la feuille protégée. Une police blanche ne cache pas la formule dans la barre de formule." } },
  { level: 5,
    ar: { q: "ماذا يفعل الاختصار Ctrl+سهم لأسفل داخل عمود مليء بالبيانات؟", o: ["ينقلك إلى آخر خلية غير فارغة قبل أول فراغ في العمود", "ينزل خلية واحدة", "يحدد العمود كله", "ينقلك إلى الورقة التالية"], e: "Ctrl+الأسهم تقفز إلى حافة منطقة البيانات، وتصبح أداة تحديد سريعة مع Shift: Ctrl+Shift+سهم لأسفل يحدد حتى آخر البيانات." },
    en: { q: "What does Ctrl+Down Arrow do inside a column full of data?", o: ["Jumps to the last non-empty cell before the first gap in the column", "Moves down one cell", "Selects the whole column", "Goes to the next sheet"], e: "Ctrl+arrows jump to the edge of the data region; add Shift for fast selection: Ctrl+Shift+Down selects to the end of the data." },
    fr: { q: "Que fait Ctrl+Flèche bas dans une colonne remplie de données ?", o: ["Il saute à la dernière cellule non vide avant le premier trou de la colonne", "Il descend d'une cellule", "Il sélectionne toute la colonne", "Il passe à la feuille suivante"], e: "Ctrl+flèches sautent au bord de la zone de données ; avec Maj, sélection rapide : Ctrl+Maj+Flèche bas sélectionne jusqu'à la fin des données." } },
  { level: 5,
    ar: { q: "خارج وضع تحرير المعادلة، ماذا يفعل المفتاح F4 بعد أن طبّقت لونًا على خلية؟", o: ["يكرر آخر إجراء (يطبّق اللون نفسه على الخلية المحددة الجديدة)", "يُثبّت المراجع بعلامة $", "يغلق المصنف", "يفتح نافذة البحث"], e: "F4 له وظيفتان: داخل المعادلة يبدّل أنواع المراجع ($)، وخارجها يكرر آخر إجراء (تنسيق، إدراج صف، حذف…). أما Alt+F4 فيغلق النافذة." },
    en: { q: "Outside formula editing, what does F4 do after you have applied a colour to a cell?", o: ["Repeats the last action (applies the same colour to the newly selected cell)", "Adds $ signs to references", "Closes the workbook", "Opens the Find box"], e: "F4 has two jobs: inside a formula it toggles reference types ($); outside it repeats the last action (formatting, inserting a row, deleting…). Alt+F4 closes the window." },
    fr: { q: "Hors modification de formule, que fait F4 après avoir appliqué une couleur à une cellule ?", o: ["Il répète la dernière action (applique la même couleur à la nouvelle cellule sélectionnée)", "Il ajoute des $ aux références", "Il ferme le classeur", "Il ouvre la boîte Rechercher"], e: "F4 a deux rôles : dans une formule il alterne les types de références ($) ; ailleurs il répète la dernière action (mise en forme, insertion de ligne, suppression…). Alt+F4 ferme la fenêtre." } },
  { level: 5,
    ar: { q: "ماذا يفعل الاختصار Ctrl+` (العلامة تحت مفتاح Esc)؟", o: ["يُظهر كل المعادلات في الورقة بدل نتائجها، والضغط مجددًا يعيد النتائج", "يحذف كل المعادلات", "يحسب الورقة من جديد", "يفتح محرر VBA"], e: "مفيد جدًا لمراجعة الورقة والتأكد من المعادلات دفعة واحدة. نفس الأمر من: صيغ ← إظهار الصيغ." },
    en: { q: "What does Ctrl+` (the key under Esc) do?", o: ["Shows every formula in the sheet instead of its result; press again to return", "Deletes all formulas", "Recalculates the sheet", "Opens the VBA editor"], e: "Very handy for auditing a sheet and checking all formulas at once. Same as Formulas → Show Formulas." },
    fr: { q: "Que fait Ctrl+` (la touche sous Échap sur un clavier QWERTY) ?", o: ["Afficher toutes les formules de la feuille au lieu de leurs résultats ; un nouvel appui les rétablit", "Supprimer toutes les formules", "Recalculer la feuille", "Ouvrir l'éditeur VBA"], e: "Très pratique pour auditer une feuille et vérifier toutes les formules d'un coup. Équivaut à Formules → Afficher les formules." } },
  { level: 5,
    ar: { q: "في A2:A50 أسماء كاملة. كتبت في B2 الاسم الأول فقط يدويًا، ثم ضغطت Ctrl+E في B3. ماذا يحدث؟", o: ["التعبئة السريعة (Flash Fill) تستنتج النمط وتملأ بقية الأسماء الأولى", "يُفتح مربع البحث", "تُحذف الأعمدة الفارغة", "يُحفظ الملف"], e: "Flash Fill (منذ إكسل 2013) يتعرف على النمط من مثالك ويطبقه. النتيجة قيم ثابتة لا معادلات، فلا تتحدث إذا تغيرت البيانات الأصلية." },
    en: { q: "A2:A50 holds full names. You type just the first name in B2, then press Ctrl+E in B3. What happens?", o: ["Flash Fill detects the pattern and fills in the remaining first names", "The Find box opens", "Empty columns are deleted", "The file is saved"], e: "Flash Fill (since Excel 2013) learns the pattern from your example and applies it. The results are fixed values, not formulas, so they will not update if the source changes." },
    fr: { q: "A2:A50 contient des noms complets. Vous tapez seulement le prénom en B2, puis Ctrl+E en B3. Que se passe-t-il ?", o: ["Le remplissage instantané (Flash Fill) détecte le modèle et complète les autres prénoms", "La boîte Rechercher s'ouvre", "Les colonnes vides sont supprimées", "Le fichier est enregistré"], e: "Le remplissage instantané (depuis Excel 2013) apprend le modèle à partir de votre exemple. Les résultats sont des valeurs fixes, pas des formules : ils ne suivent pas les changements de la source." } },
  { level: 5,
    ar: { q: "ما الاختصار الذي ينقلك إلى ورقة العمل التالية في المصنف؟", o: ["Ctrl+Page Down", "Ctrl+Tab", "Alt+→", "Shift+Page Down"], e: "Ctrl+Page Down للورقة التالية وCtrl+Page Up للسابقة. أما Ctrl+Tab فيتنقل بين المصنفات المفتوحة." },
    en: { q: "Which shortcut moves to the next worksheet in the workbook?", o: ["Ctrl+Page Down", "Ctrl+Tab", "Alt+→", "Shift+Page Down"], e: "Ctrl+Page Down goes to the next sheet and Ctrl+Page Up to the previous one. Ctrl+Tab switches between open workbooks." },
    fr: { q: "Quel raccourci passe à la feuille suivante du classeur ?", o: ["Ctrl+Pg.Suiv", "Ctrl+Tab", "Alt+→", "Maj+Pg.Suiv"], e: "Ctrl+Pg.Suiv va à la feuille suivante et Ctrl+Pg.Préc à la précédente. Ctrl+Tab bascule entre les classeurs ouverts." } },
  { level: 5,
    ar: { q: "بأي صيغة يجب حفظ مصنف يحتوي ماكرو حتى لا تُفقد الشيفرة؟", o: [".xlsm", ".xlsx", ".csv", ".xltx"], e: "‎.xlsm‎ = مصنف ممكّن للماكرو. عند الحفظ بـ ‎.xlsx‎ يحذّرك إكسل لأن هذه الصيغة لا تحفظ شيفرة VBA فتُحذف." },
    en: { q: "Which format must a workbook with macros be saved in so the code is not lost?", o: [".xlsm", ".xlsx", ".csv", ".xltx"], e: ".xlsm = macro-enabled workbook. If you save as .xlsx, Excel warns you because that format cannot store VBA code, so it is removed." },
    fr: { q: "Dans quel format enregistrer un classeur contenant des macros pour ne pas perdre le code ?", o: [".xlsm", ".xlsx", ".csv", ".xltx"], e: ".xlsm = classeur prenant en charge les macros. En .xlsx, Excel avertit que ce format ne peut pas stocker le code VBA, qui est alors supprimé." } },
  { level: 5,
    ar: { q: "ما اللغة التي تُكتب بها وحدات الماكرو في إكسل؟", o: ["VBA (Visual Basic for Applications)", "Python فقط", "HTML", "SQL"], e: "VBA مدمجة في كل تطبيقات Office لأتمتة المهام المتكررة. (توفر الإصدارات الحديثة أيضًا Python in Excel وOffice Scripts، لكن الماكرو الكلاسيكي هو VBA)." },
    en: { q: "In which language are Excel macros written?", o: ["VBA (Visual Basic for Applications)", "Python only", "HTML", "SQL"], e: "VBA is built into every Office app to automate repetitive tasks. (Recent versions also offer Python in Excel and Office Scripts, but classic macros are VBA.)" },
    fr: { q: "Dans quel langage les macros Excel sont-elles écrites ?", o: ["VBA (Visual Basic for Applications)", "Uniquement Python", "HTML", "SQL"], e: "VBA est intégré à toutes les applications Office pour automatiser les tâches répétitives. (Les versions récentes offrent aussi Python dans Excel et Office Scripts, mais les macros classiques sont en VBA.)" } },
  { level: 5,
    ar: { q: "ما وظيفة «مسجّل الماكرو» (Record Macro)؟", o: ["يسجّل خطواتك في إكسل ويحوّلها تلقائيًا إلى شيفرة VBA يمكن إعادة تشغيلها", "يسجّل صوتك أثناء العمل", "يصوّر الشاشة فيديو", "يحفظ نسخة احتياطية كل دقيقة"], e: "من تبويب «المطور» (أو عرض ← وحدات الماكرو) ← تسجيل ماكرو. طريقة ممتازة لتعلم VBA: سجّل مهمة ثم افتح الشيفرة الناتجة واقرأها." },
    en: { q: "What does the macro recorder (Record Macro) do?", o: ["Records your steps in Excel and turns them into VBA code you can replay", "Records your voice while you work", "Captures a screen video", "Saves a backup every minute"], e: "Developer tab (or View → Macros) → Record Macro. A great way to learn VBA: record a task, then open and read the generated code." },
    fr: { q: "Que fait l'enregistreur de macros ?", o: ["Il enregistre vos actions dans Excel et les convertit en code VBA rejouable", "Il enregistre votre voix pendant le travail", "Il filme l'écran", "Il fait une sauvegarde chaque minute"], e: "Onglet Développeur (ou Affichage → Macros) → Enregistrer une macro. Excellent moyen d'apprendre VBA : enregistrez une tâche puis lisez le code généré." } },
  { level: 5,
    ar: { q: "ما الاختصار الذي يفتح محرر Visual Basic (VBE)؟", o: ["Alt+F11", "Alt+F8", "Ctrl+F11", "F11"], e: "Alt+F11 يفتح المحرر لكتابة الشيفرة وتعديلها، وAlt+F8 يفتح قائمة وحدات الماكرو لتشغيلها، وF11 ينشئ مخططًا." },
    en: { q: "Which shortcut opens the Visual Basic Editor (VBE)?", o: ["Alt+F11", "Alt+F8", "Ctrl+F11", "F11"], e: "Alt+F11 opens the editor to write and edit code; Alt+F8 opens the macro list to run one; F11 creates a chart." },
    fr: { q: "Quel raccourci ouvre l'éditeur Visual Basic (VBE) ?", o: ["Alt+F11", "Alt+F8", "Ctrl+F11", "F11"], e: "Alt+F11 ouvre l'éditeur pour écrire et modifier le code ; Alt+F8 ouvre la liste des macros pour en exécuter une ; F11 crée un graphique." } },
  { level: 5,
    ar: { q: "فتحت ملف .xlsm من الإنترنت فظهر شريط أمان يقول إن وحدات الماكرو معطّلة. ما التصرف الصحيح؟", o: ["تمكين المحتوى فقط إذا كان الملف من مصدر موثوق، لأن الماكرو قد يحتوي شيفرة ضارة", "تمكينه دائمًا لأن الماكرو آمن", "حذف الملف فورًا مهما كان مصدره", "تحويله إلى PDF لتشغيل الماكرو"], e: "الماكرو برنامج حقيقي يمكنه تعديل الملفات أو تنزيل برمجيات. لذلك يعطّله إكسل افتراضيًا (وتُحظر ماكرو ملفات الإنترنت في الإصدارات الحديثة). فعّله للملفات الموثوقة فقط." },
    en: { q: "You open an .xlsm file from the internet and a security bar says macros are disabled. What is the right action?", o: ["Enable content only if the file comes from a trusted source, because macros can contain malicious code", "Always enable it, macros are safe", "Delete the file immediately whatever its source", "Convert it to PDF to run the macros"], e: "A macro is a real program that can change files or download software. That is why Excel disables them by default (and recent versions block macros in internet files). Enable them only for trusted files." },
    fr: { q: "Vous ouvrez un fichier .xlsm venant d'Internet et une barre de sécurité indique que les macros sont désactivées. Que faire ?", o: ["Activer le contenu seulement si le fichier provient d'une source fiable, car une macro peut contenir du code malveillant", "Toujours l'activer, les macros sont sûres", "Supprimer le fichier immédiatement quelle que soit sa source", "Le convertir en PDF pour exécuter les macros"], e: "Une macro est un vrai programme capable de modifier des fichiers ou de télécharger des logiciels. Excel les désactive donc par défaut (et les versions récentes bloquent les macros des fichiers Internet). Activez-les seulement pour des fichiers fiables." } },
];
